    public enum AgentDecisionType { Message, Read, Write, MultiTool, Clarification, Invalid }
    internal sealed class AgentDecision { public AgentDecisionType Type { get; set; } public string Content { get; set; } public IList<AgentToolCall> Calls { get; set; } public AgentDecision() { Calls = new List<AgentToolCall>(); } }
    public sealed class AgentDryRunResult
    {
        public string Intent { get; set; } public IList<int> TargetIndexes { get; set; } public string TargetKeyword { get; set; } public string Reference { get; set; } public string Title { get; set; } public string Status { get; set; } public string DueDate { get; set; } public string DecisionType { get; set; } public string Path { get; set; } public string FailureReason { get; set; }
        public AgentDryRunResult() { TargetIndexes = new List<int>(); }
        public string Display { get { return Intent + " | targets: [" + string.Join(",", TargetIndexes) + "] | status: " + (Status ?? "null") + " | " + (FailureReason ?? "DRY_RUN_BLOCKED_BEFORE_EXECUTION"); } }
    }

    public sealed class AgentConversationService : IAgentService
    {
        private readonly AgentToolExecutor executor; private readonly TaskService tasks; private readonly ConversationContext context; private readonly RuleBasedAgentService fallback; private readonly IAgentLogger logger; private readonly IClock clock; private readonly ILocalIntentClassifier classifier; private readonly TaskEntityExtractor entities = new TaskEntityExtractor(); private readonly IntentSafetyEvaluator safety = new IntentSafetyEvaluator(); private readonly LocalLlmSettings localLlmSettings; private readonly IHybridCommandInterpreter hybridInterpreter; private readonly bool disablePersistentExecutionLog; private readonly int hybridTimeoutSeconds; private readonly WorkspaceService workspaces; private string contextWorkspaceId;
        public AgentConversationService(AiProviderManager providers, IAiContextBuilder contextBuilder, AgentToolExecutor executor, TaskService tasks, ConversationContext context, RuleBasedAgentService fallback, AiProviderOptions options, IAgentLogger logger, IClock clock) : this(providers, contextBuilder, executor, tasks, context, fallback, options, logger, clock, null, false) { }
        public AgentConversationService(AiProviderManager providers, IAiContextBuilder contextBuilder, AgentToolExecutor executor, TaskService tasks, ConversationContext context, RuleBasedAgentService fallback, AiProviderOptions options, IAgentLogger logger, IClock clock, ILocalLlmService localLlm, bool disablePersistentExecutionLog, int? hybridTimeoutSeconds = null, WorkspaceService workspaces = null) { this.executor = executor; this.tasks = tasks; this.context = context; this.fallback = fallback; this.logger = logger; this.clock = clock; this.workspaces=workspaces; this.disablePersistentExecutionLog = disablePersistentExecutionLog; classifier = new TfIdfIntentClassifier(new IntentTrainingDataRepository()); localLlmSettings = LocalLlmSettings.Load(); this.hybridTimeoutSeconds = hybridTimeoutSeconds ?? localLlmSettings.TimeoutSeconds; ILocalLlmService effectiveLlm = localLlm ?? new GraniteOllamaService(localLlmSettings.Endpoint, TimeSpan.FromSeconds(localLlmSettings.TimeoutSeconds)); hybridInterpreter = new HybridCommandInterpreter(this, effectiveLlm); }
        public async Task<AgentResponse> ProcessAsync(AgentRequest request)
        {
            string input = request == null ? "" : (request.Message ?? "").Trim(); IDisposable workspaceScope=null; GitHubWorkspace requestedWorkspace=null; if(workspaces!=null){Match switchMatch=Regex.Match(input,"^(.+?)(?:으로|로)\\s*(?:바꿔|전환|돌아가)",RegexOptions.IgnoreCase);if(switchMatch.Success&&!Regex.IsMatch(switchMatch.Groups[1].Value,"긴급|우선순위|중요도|\\d+\\s*번",RegexOptions.IgnoreCase)){GitHubWorkspace target=workspaces.Resolve(switchMatch.Groups[1].Value.Trim());if(target==null)return Response(false,workspaces.IsAmbiguous(switchMatch.Groups[1].Value)?"AMBIGUOUS_WORKSPACE: 작업 공간을 특정하지 못했습니다.":"WORKSPACE_NOT_FOUND: 작업 공간을 찾지 못했습니다.",null);workspaces.SetActive(target);context.Clear();contextWorkspaceId=null;return Response(true,target.DisplayName+"으로 작업 공간을 변경했습니다.",null);}requestedWorkspace=workspaces.Workspaces.OrderByDescending(x=>(x.DisplayName??"").Length).FirstOrDefault(x=>Regex.IsMatch(input,"(^|\\s)"+Regex.Escape(x.DisplayName??x.Repository)+"(?=에|의|\\s|$)",RegexOptions.IgnoreCase));if(requestedWorkspace!=null){workspaceScope=workspaces.Use(requestedWorkspace.Id);input=Regex.Replace(input,"^"+Regex.Escape(requestedWorkspace.DisplayName)+"(?:에|의)?\\s*","",RegexOptions.IgnoreCase);contextWorkspaceId=requestedWorkspace.Id;}else if(context.DisplayedTasks.Count>0&&!string.IsNullOrWhiteSpace(contextWorkspaceId)&&Regex.IsMatch(input,"\\d+\\s*번|첫\\s*번째|두\\s*번째|세\\s*번째"))workspaceScope=workspaces.Use(contextWorkspaceId);else contextWorkspaceId=workspaces.ActiveWorkspace.Id;} Stopwatch watch = Stopwatch.StartNew(); bool fallbackUsed = false;
            try
            {
                logger.Info("Raw User Message", SafeLog(input)); logger.Info("Normalized Message", Normalize(input)); logger.Info("Expression Evidence", "actionVerb=" + DetectActionVerb(input) + ",readExpression=" + DetectReadExpression(input)); logger.Info("Dialog State Before", DescribeState()); AgentResponse pending = await HandlePendingAsync(input); if (pending != null) return pending;
                if (IsClearConversationRequest(input)) { context.Clear(); fallback.ResetContext(); AgentResponse cleared = Response(true, "대화 기록을 비우고 새 대화를 시작했습니다. 업무와 GitHub 데이터는 변경하지 않았습니다.", null); cleared.ClearConversation = true; return cleared; }
                if (Regex.IsMatch(input, "제목(?:은|으로|:)") && !IsCreateRequest(Normalize(input))) { TaskEntityExtractionResult extracted = entities.ExtractForCreate(input); if (extracted.HasTitle) { PendingAgentAction createPending = new PendingAgentAction { ActionType = PendingAgentActionType.CreateTask, Need = PendingAgentNeed.Confirmation, CreatedAt = clock.Now }; createPending.Arguments["title"] = extracted.Title; createPending.Arguments["description"] = extracted.Description ?? ""; DateRange pendingRange; if (new DateExpressionParser().TryParse(input, clock.Now, out pendingRange)) createPending.Arguments["dueDate"] = pendingRange.StartDate.ToString("yyyy-MM-dd"); context.SetPending(createPending); return Response(false, "제목: " + extracted.Title + "\n이 내용으로 등록할까요?", null); } }
                AgentDecision decision = await BuildExplicitWriteDecisionAsync(input); IntentClassificationResult classified = classifier.Classify(input); logger.Info("Intent Classification", "intent=" + classified.Intent + ",confidence=" + classified.Confidence.ToString("0.000") + ",second=" + classified.SecondIntent + ",secondConfidence=" + classified.SecondConfidence.ToString("0.000") + ",matched=" + SafeLog(classified.MatchedExample) + ",accepted=" + classified.Accepted + ",explicitRule=" + (decision != null)); if (decision == null && classified.Accepted && classified.Intent == LocalIntent.ClearConversation) { context.Clear(); fallback.ResetContext(); AgentResponse cleared = Response(true, "대화 기록을 비우고 새 대화를 시작했습니다. 업무와 GitHub 데이터는 변경하지 않았습니다.", null); cleared.ClearConversation = true; return cleared; } if (decision == null) decision = classified.Accepted ? await BuildClassifiedDecisionAsync(classified.Intent, input) : null; if (decision == null || decision.Type == AgentDecisionType.Invalid) { fallbackUsed = true; decision = await BuildSafeDecisionAsync(input); }
                HybridExecution bridge = await ApplyHybridAsync(input, decision); if (bridge.BlockedResponse != null) { ApplyInterpreterMetadata(bridge.BlockedResponse, bridge); SaveHybridExecution(input, bridge, bridge.BlockedResponse, watch.ElapsedMilliseconds); return bridge.BlockedResponse; } decision = bridge.Decision;
                LogCreateCommand(input, decision, bridge); LogDecision(input, decision, fallbackUsed); AgentResponse executed = await ExecuteDecisionAsync(decision, input, fallbackUsed); ApplyInterpreterMetadata(executed, bridge); SaveHybridExecution(input, bridge, executed, watch.ElapsedMilliseconds); return executed;
            }
            catch (Exception ex) { logger.Error("Conversation Agent", ex); return Response(false, "처리 중 문제가 발생했습니다. Local 업무 데이터는 변경하지 않았습니다.", null); }
            finally { if(workspaceScope!=null)workspaceScope.Dispose(); logger.Info("Dialog State After", DescribeState()); logger.Info("Conversation Trace", "elapsed=" + watch.ElapsedMilliseconds + ",lastTool=" + (context.LastToolCall ?? "none") + ",taskId=" + (context.LastReferencedTaskId.HasValue ? context.LastReferencedTaskId.ToString() : "none") + ",pending=" + (context.PendingAction == null ? "none" : context.PendingAction.ActionType.ToString())); }
        }
        public void ResetContext() { context.Clear(); fallback.ResetContext(); }

        public async Task<AgentDryRunResult> AnalyzeDryRunAsync(string input, IList<WorkTask> candidateTasks)
        {
            context.Clear(); fallback.ResetContext(); List<WorkTask> candidates = (candidateTasks ?? new List<WorkTask>()).ToList(); context.SetDisplayedTasks(candidates, clock.Now); context.RecordRead(candidates.Select(x => x.Id));
            AgentDecision decision = await BuildExplicitWriteDecisionAsync((input ?? "").Trim()); IntentClassificationResult classified = classifier.Classify(input ?? ""); bool fallbackUsed = false;
            if (decision == null) decision = classified.Accepted ? await BuildClassifiedDecisionAsync(classified.Intent, input ?? "") : null;
            if (decision == null || decision.Type == AgentDecisionType.Invalid) { fallbackUsed = true; decision = await BuildSafeDecisionAsync(input ?? ""); }
            AgentDryRunResult result = new AgentDryRunResult { DecisionType = decision == null ? "Invalid" : decision.Type.ToString(), Path = "AgentConversationService:Parser>Resolver>DryRun", FailureReason = "EXECUTION_BLOCKED" };
            IList<AgentToolCall> calls = decision == null ? new List<AgentToolCall>() : decision.Calls; string[] tools = calls.Select(x => x.Tool).ToArray();
            if (tools.Any(x => x == "create_task")) result.Intent = "CREATE_TASK"; else if (tools.Any(IsTargetWrite) || tools.Any(x => x == "update_task_description" || x == "add_task_memo")) result.Intent = "UPDATE_TASK"; else if (tools.Any(x => x == "delete_task" || x == "delete_tasks")) result.Intent = "DELETE_TASK"; else if (decision != null && (decision.Type == AgentDecisionType.Read || tools.Any())) result.Intent = "READ_TASK"; else result.Intent = "UNKNOWN";
            if (tools.Any(x => x == "complete_task")) result.Status = "Done"; else if (tools.Any(x => x == "start_task")) result.Status = "InProgress"; else if (tools.Any(x => x == "block_task")) result.Status = "Blocked"; else if (tools.Any(x => x == "reopen_task")) result.Status = "Todo";
            if (result.Intent == "UNKNOWN" && IsRecentReferenceAction(input)) { if (IsStatusWriteRequest(input, "start_task")) { result.Intent = "UPDATE_TASK"; result.Status = "InProgress"; } else if (IsStatusWriteRequest(input, "complete_task")) { result.Intent = "UPDATE_TASK"; result.Status = "Done"; } if (result.Intent == "UPDATE_TASK") result.Reference = "LAST_CREATED"; }
            foreach (AgentToolCall call in calls) { Guid id; if (!Guid.TryParse(Value(call, "taskId"), out id)) continue; int index = candidates.FindIndex(x => x.Id == id); if (index >= 0 && !result.TargetIndexes.Contains(index + 1)) result.TargetIndexes.Add(index + 1); }
            result.TargetKeyword = calls.Select(x => Value(x, "query")).FirstOrDefault(x => !string.IsNullOrWhiteSpace(x)); result.Title = calls.Where(x => x.Tool == "create_task").Select(x => Value(x, "title")).FirstOrDefault(); result.DueDate = calls.Where(x => x.Tool == "create_task").Select(x => Value(x, "dueDate")).FirstOrDefault(); if (calls.Any(x => x.Tool == "get_recent_tasks") && Regex.IsMatch(input ?? "", "(방금|아까).*(만든|등록)")) result.Reference = "LAST_CREATED";
            if (decision == null || decision.Type == AgentDecisionType.Clarification || decision.Type == AgentDecisionType.Invalid) result.FailureReason = fallbackUsed ? "UNRESOLVED_AFTER_FALLBACK" : "UNRESOLVED_OR_CLARIFICATION";
            return result;
        }

        private async Task<AgentDecision> BuildExplicitWriteDecisionAsync(string input)
        {
            if(HasAmbiguousTime(input))return Clarify("오전인지 오후인지 확인해 주세요. 예: 오후 3시 또는 15시. 업무는 변경하지 않았습니다.");
            if(IsReminderToggleRequest(input))return await BuildReminderDecisionAsync(input);
            if(IsTimeUpdateRequest(input))return await BuildTimeUpdateDecisionAsync(input);
            if (IsDueDateUpdateRequest(input)) return await BuildDueDateUpdateDecisionAsync(input);
            if (IsPriorityUpdateRequest(input)) return await BuildPriorityUpdateDecisionAsync(input);
            if(IsCurrentWorkspaceOverviewRequest(input))return BuildReadDecision(input);
            if (IsWorkBriefingRequest(input)) return Read(Call("work_briefing","mode",Regex.IsMatch(input??"","급한|중요한.*남았",RegexOptions.IgnoreCase)?"urgent":"today"));
            AgentDecision multiAction = BuildMultiActionDecision(input); if (multiAction == null) multiAction = await BuildNamedMultiActionDecisionAsync(input); if (multiAction != null) return await ValidateMultiActionDecisionAsync(multiAction);
            if (IsCreateRequest(Normalize(input))) return BuildCreateDecision(input);
            if (IsSimpleDateReadQuery(input)) return BuildReadDecision(input);
            if (context.LastResponseType == "TASK_SUMMARY" && Regex.IsMatch(input ?? "", "(왜|뭔데|무엇|뭐|목록).*(개|건)|(?:두|2)\\s*(?:개|건).*(뭐|왜|뭔데|목록)")) { AgentToolCall summary = Call("search_tasks", "status", "Todo"); return Read(summary); }
            if (IsDescriptionWriteRequest(input)) return await BuildDescriptionDecisionAsync(input);
            IntentEvidence evidence = safety.Evaluate(input); logger.Info("Intent Evidence", "read=" + evidence.ReadEvidence + ",write=" + evidence.WriteEvidence); if (evidence.HasReadEvidence || IsLikelyTaskRead(input)) return BuildReadDecision(input);
            if (IsRecentReferenceAction(input)) { if (IsStatusWriteRequest(input, "start_task")) return await BuildStatusDecisionAsync("start_task", input); if (IsStatusWriteRequest(input, "complete_task")) return await BuildStatusDecisionAsync("complete_task", input); }
            string normalized = Normalize(input); if (IsDescriptionRequest(input)) return await BuildDescriptionDecisionAsync(input); if (IsDeleteRequest(normalized)) return await BuildDeletePreviewDecisionAsync(normalized); if (IsMemoRequest(normalized)) return await BuildMemoDecisionAsync(input); if (Contains(normalized, "로컬에도 가져", "업무로 가져", "슬레이브스플릿에 가져")) { int? issue = context.LastReferencedGitHubIssueNumber ?? context.LastCreatedGitHubIssueNumber; return issue.HasValue ? Write(Call("import_github_issue", "issueNumber", issue.Value.ToString())) : Clarify("가져올 GitHub Issue 번호를 알려주세요."); } if (IsCreateRequest(normalized)) return BuildCreateDecision(input); if (IsStatusQuestion(input)) return BuildReadDecision(input); if (IsStatusWriteRequest(input, "start_task")) return await BuildStatusDecisionAsync("start_task", input); if (IsStatusWriteRequest(input, "complete_task")) return await BuildStatusDecisionAsync("complete_task", input); if (IsStatusWriteRequest(input, "block_task")) return await BuildStatusDecisionAsync("block_task", input); return null;
        }

        private async Task<AgentDecision> BuildDueDateUpdateDecisionAsync(string input)
        {
            string text = input ?? ""; bool remove = Regex.IsMatch(text, "(일정|날짜)\\s*(을|를)?\\s*(없애|지워|제거)", RegexOptions.IgnoreCase); DateRange date = null;
            if (!remove && !new DateExpressionParser().TryParse(text, clock.Now, out date)) return Clarify("INVALID_DATE: 변경할 날짜가 올바르지 않습니다. 변경된 업무는 없습니다.");
            string indexed = Regex.Replace(text, "첫\\s*번째", "1번"); indexed = Regex.Replace(indexed, "두\\s*번째", "2번"); indexed = Regex.Replace(indexed, "세\\s*번째", "3번"); List<int> indexes = ExtractCandidateIndexes(indexed); List<Guid> targets = new List<Guid>();
            if (indexes.Count > 0) { if (indexes.Any(x => x < 1 || x > context.DisplayedTasks.Count)) return Clarify("TARGET_NOT_FOUND: " + CandidateRangeMessage() + " 변경된 업무는 없습니다."); targets.AddRange(context.ResolveMany(indexes)); }
            if (targets.Count == 0 && Regex.IsMatch(text, "방금|마지막에|마지막으로|이 업무|그 업무") && context.LastCreatedTaskId.HasValue) targets.Add(context.LastCreatedTaskId.Value);
            if (targets.Count == 0)
            {
                IReadOnlyList<WorkTask> all = await tasks.GetAllAsync(); string normalizedInput = Normalize(text); List<WorkTask> exactReferences = all.Where(x => !string.IsNullOrWhiteSpace(x.Title) && normalizedInput.Contains(Normalize(x.Title))).ToList(); if (exactReferences.Count == 1) targets.Add(exactReferences[0].Id); else { string query = Regex.Replace(text, "(다음\\s*주\\s*[월화수목금토일]요일|이번\\s*주\\s*[월화수목금토일]요일|\\d{4}[-./]\\d{1,2}[-./]\\d{1,2}|\\d{1,2}\\s*월\\s*\\d{1,2}\\s*일|내일로|오늘로|모레로|어제로|오늘|내일|모레|어제|일정|날짜|업무|미뤄|옮겨|변경|바꿔|하는\\s*걸로|하자|해줘|줘|없애|지워|제거)", " ", RegexOptions.IgnoreCase); query = Regex.Replace(query, "(?<=\\S)(은|는|이|가|을|를)(?=\\s|$)", " "); string[] tokens = Tokens(query); List<WorkTask> matches = all.Where(x => tokens.Length > 0 && tokens.All(t => Normalize(x.Title).Contains(t))).ToList(); if (matches.Count > 1 || exactReferences.Count > 1) return Clarify("AMBIGUOUS_TARGET: 대상 업무가 여러 개입니다. 변경된 업무는 없습니다."); if (matches.Count == 1) targets.Add(matches[0].Id); }
            }
            if (targets.Count == 0) return Clarify("TARGET_NOT_FOUND: 변경할 업무를 찾지 못했습니다. 변경된 업무는 없습니다.");
            AgentDecision decision = new AgentDecision { Type = AgentDecisionType.Write }; string label = remove ? null : DateUpdateLabel(text, date.StartDate); foreach (Guid id in targets.Distinct()) { AgentToolCall call = Call("update_task_due_date", "taskId", id.ToString()); if (remove) call.Arguments["remove"] = "true"; else { call.Arguments["dueDate"] = date.StartDate.ToString("yyyy-MM-dd"); call.Arguments["dateLabel"] = label; } decision.Calls.Add(call); } return decision;
        }
        private static bool IsDueDateUpdateRequest(string input) { string text = input ?? ""; if (Regex.IsMatch(text, "등록|추가|만들", RegexOptions.IgnoreCase)) return false; if (Regex.IsMatch(text, "(일정|날짜)\\s*(을|를)?\\s*(없애|지워|제거)", RegexOptions.IgnoreCase)) return true; if (!Regex.IsMatch(text, "미뤄|옮겨|변경|바꿔|하자|하는\\s*걸로", RegexOptions.IgnoreCase)) return false; DateRange ignored; return new DateExpressionParser().TryParse(text, DateTime.Today, out ignored) || Regex.IsMatch(text, "\\d{1,2}\\s*월\\s*\\d{1,2}\\s*일|\\d{4}[-./]\\d{1,2}[-./]\\d{1,2}"); }
        private static string DateUpdateLabel(string input, DateTime date) { string text = input ?? ""; if (text.Contains("오늘")) return "오늘"; if (text.Contains("내일")) return "내일"; if (text.Contains("모레")) return "모레"; if (text.Contains("어제")) return "어제"; return date.ToString("yyyy-MM-dd"); }
        private static bool IsPriorityUpdateRequest(string input){string text=input??"";if(Regex.IsMatch(text,"등록|추가|생성|만들"))return false;return Regex.IsMatch(text,"(우선순위|중요도).*(높|낮|보통|일반|기본|긴급|최우선)|(?:긴급|최우선|급함|높음|중요|낮음|안\\s*급함)(?:으로)?\\s*(?:바꿔|변경|해줘)",RegexOptions.IgnoreCase);}
        private async Task<AgentDecision> BuildPriorityUpdateDecisionAsync(string input){TaskPriority priority;string label;if(!TryPriority(input,out priority,out label))return Clarify("INVALID_PRIORITY: 우선순위를 확인하지 못했습니다.");List<int> requested=ExtractCandidateIndexes(input);if(requested.Any(x=>x<1||x>context.DisplayedTasks.Count))return Clarify("TARGET_NOT_FOUND: "+CandidateRangeMessage());IReadOnlyList<Guid> references=ResolveCandidateReferences(input);if(references.Count==0){string query=Regex.Replace(input??"","(우선순위|중요도|긴급으로?|최우선|급함|높게|높음|중요한?|낮게|낮음|안\\s*급함|보통|일반|기본|바꿔|변경|해줘|줘|업무|은|는|이|가|을|를)"," ",RegexOptions.IgnoreCase);string[] tokens=Tokens(query);IReadOnlyList<WorkTask> all=await tasks.GetAllAsync();List<WorkTask> matches=all.Where(x=>tokens.Length>0&&tokens.All(t=>Normalize(x.Title).Contains(t))).ToList();if(matches.Count>1)return Clarify("AMBIGUOUS_TARGET: 대상 업무가 여러 개입니다.");if(matches.Count==1)references=new List<Guid>{matches[0].Id}.AsReadOnly();}if(references.Count==0)return Clarify("TARGET_NOT_FOUND: 변경할 업무를 찾지 못했습니다.");AgentDecision decision=new AgentDecision{Type=AgentDecisionType.Write};foreach(Guid id in references){AgentToolCall call=Call("update_task_priority","taskId",id.ToString());call.Arguments["priority"]=priority.ToString();call.Arguments["priorityLabel"]=label;decision.Calls.Add(call);}return decision;}
        private static bool TryPriority(string input,out TaskPriority priority,out string label){string text=input??"";if(Regex.IsMatch(text,"긴급|최우선|급함",RegexOptions.IgnoreCase)){priority=TaskPriority.Critical;label="긴급";return true;}if(Regex.IsMatch(text,"낮음|낮게|안\\s*급함",RegexOptions.IgnoreCase)){priority=TaskPriority.Low;label="낮음";return true;}if(Regex.IsMatch(text,"높음|높게|중요",RegexOptions.IgnoreCase)){priority=TaskPriority.High;label="높음";return true;}if(Regex.IsMatch(text,"보통|일반|기본",RegexOptions.IgnoreCase)){priority=TaskPriority.Normal;label="보통";return true;}priority=TaskPriority.Normal;label=null;return false;}
        private static bool IsWorkBriefingRequest(string input){string text=(input??"").Trim();if(Regex.IsMatch(text,"^(오늘\\s*)?업무$"))return false;return Regex.IsMatch(text,"(지금|오늘).*(뭐\\s*해야|뭐부터|할\\s*일\\s*정리|업무\\s*정리|손대)|급한\\s*(거|것).*뭐|중요한\\s*(일|것).*남았",RegexOptions.IgnoreCase);}
        private static bool IsCurrentWorkspaceOverviewRequest(string input){string text=Normalize(input);if(text.Contains("오늘"))return false;return Regex.IsMatch(text,"^(?:현재\\s*업무|내\\s*업무|업무\\s*현황|전체\\s*업무)(?:\\s*(?:좀)?\\s*(?:보여\\s*줘|알려\\s*줘|확인해\\s*줘)?)?$",RegexOptions.IgnoreCase)||Regex.IsMatch(text,"^지금\\s*업무\\s*(?:뭐|무엇).*(?:있어|있나)",RegexOptions.IgnoreCase);}
        private static bool IsReminderToggleRequest(string input){string text=input??"";return !Regex.IsMatch(text,"등록|추가|생성")&&Regex.IsMatch(text,"알림\\s*(켜|꺼|없애|제거)",RegexOptions.IgnoreCase);}
        private static bool IsTimeUpdateRequest(string input){string text=input??"";if(Regex.IsMatch(text,"등록|추가|생성|만들"))return false;if(Regex.IsMatch(text,"시간(?:만)?\\s*(없애|지워|제거)",RegexOptions.IgnoreCase))return true;ParsedTaskTime parsed;return new TimeExpressionParser().TryParse(text,out parsed)&&(Regex.IsMatch(text,"(?:로\\s*)?(해줘|바꿔|변경|옮겨)",RegexOptions.IgnoreCase)||Regex.IsMatch(text.Trim(),"^(?:아니\\s*)?(?:오전|오후)?\\s*\\d{1,2}(?::\\d{2}|\\s*시(?:\\s*\\d{1,2}\\s*분)?)\\s*로?[.! ]*$",RegexOptions.IgnoreCase));}
        private async Task<IReadOnlyList<Guid>> ResolveTimeTargetsAsync(string input){List<int> indexes=ExtractCandidateIndexes(input);if(indexes.Any(x=>x<1||x>context.DisplayedTasks.Count))return new List<Guid>().AsReadOnly();IReadOnlyList<Guid> ids=ResolveCandidateReferences(input);if(ids.Count>0)return ids;if(context.LastModifiedTaskId.HasValue&&context.LastChangedField=="DueTime"&&Regex.IsMatch(input??"","^(?:아니\\s*)?(?:오전|오후)?\\s*\\d",RegexOptions.IgnoreCase))return new List<Guid>{context.LastModifiedTaskId.Value}.AsReadOnly();string query=Regex.Replace(input??"","((?:오전|오후)?\\s*\\d{1,2}(?::\\d{2}|\\s*시(?:\\s*(?:\\d{1,2}\\s*분|반))?)|오늘|내일|모레|어제|시간|알림|전에|분|켜|꺼|없애|지워|제거|해줘|바꿔|변경|옮겨|업무|은|는|이|가|을|를)"," ",RegexOptions.IgnoreCase);string[] tokens=Tokens(query);IReadOnlyList<WorkTask> all=await tasks.GetAllAsync();List<WorkTask> matches=all.Where(x=>tokens.Length>0&&tokens.All(t=>Normalize(x.Title).Contains(t))).ToList();return matches.Count==1?new List<Guid>{matches[0].Id}.AsReadOnly():new List<Guid>().AsReadOnly();}
        private async Task<AgentDecision> BuildTimeUpdateDecisionAsync(string input){bool remove=Regex.IsMatch(input??"","시간(?:만)?\\s*(없애|지워|제거)",RegexOptions.IgnoreCase);ParsedTaskTime parsed=null;if(!remove&&!new TimeExpressionParser().TryParse(input,out parsed))return Clarify("INVALID_TIME: 시간을 해석하지 못했습니다.");IReadOnlyList<Guid> ids=await ResolveTimeTargetsAsync(input);if(ids.Count==0)return Clarify("TARGET_NOT_FOUND: 변경할 업무를 찾지 못했습니다.");DateRange date=null;bool hasDate=!remove&&new DateExpressionParser().TryParse(input,clock.Now,out date);AgentDecision decision=new AgentDecision{Type=AgentDecisionType.Write};foreach(Guid id in ids){AgentToolCall call=Call("update_task_time","taskId",id.ToString());if(remove)call.Arguments["remove"]="true";else{call.Arguments["dueTime"]=parsed.Time.ToString(@"hh\:mm");if(parsed.ReminderOffsetMinutes.HasValue)call.Arguments["reminderOffset"]=parsed.ReminderOffsetMinutes.Value.ToString();if(hasDate)call.Arguments["dueDate"]=date.StartDate.ToString("yyyy-MM-dd");}decision.Calls.Add(call);}return decision;}
        private async Task<AgentDecision> BuildReminderDecisionAsync(string input){IReadOnlyList<Guid> ids=await ResolveTimeTargetsAsync(input);if(ids.Count==0)return Clarify("TARGET_NOT_FOUND: 변경할 업무를 찾지 못했습니다.");bool enabled=Regex.IsMatch(input??"","알림\\s*켜",RegexOptions.IgnoreCase);AgentDecision decision=new AgentDecision{Type=AgentDecisionType.Write};foreach(Guid id in ids){AgentToolCall call=Call("update_task_reminder","taskId",id.ToString());call.Arguments["enabled"]=enabled?"true":"false";decision.Calls.Add(call);}return decision;}

        private AgentDecision BuildMultiActionDecision(string input)
        {
            string text = input ?? "";
            MatchCollection clauses = Regex.Matches(text, "(?<targets>(?:(?:\\d+\\s*번|첫\\s*번째|두\\s*번째|세\\s*번째)(?:\\s*(?:번)?\\s*(?:은|는|이|가|하고|와|과|,)?\\s*)?)+)(?:건|업무|것|거)?(?:은|는|이|가)?\\s*(?:아직|이제)?\\s*(?<status>완료|끝났|끝내|끝난|Done|진행\\s*중|하는\\s*중|작업\\s*중|보류|막힘|대기|Blocked|Todo|시작\\s*전|해야\\s*함)", RegexOptions.IgnoreCase);
            if (clauses.Count < 2) return null;
            AgentDecision decision = new AgentDecision { Type = AgentDecisionType.Write }; Dictionary<Guid, string> planned = new Dictionary<Guid, string>();
            foreach (Match clause in clauses)
            {
                string tool = MultiActionTool(clause.Groups["status"].Value); if (tool == null) return Clarify("변경할 상태를 확인하지 못했습니다. 변경된 업무는 없습니다.");
                string targetText = Regex.Replace(clause.Groups["targets"].Value, "첫\\s*번째", "1번"); targetText = Regex.Replace(targetText, "두\\s*번째", "2번"); targetText = Regex.Replace(targetText, "세\\s*번째", "3번"); List<int> indexes = ExtractCandidateIndexes(targetText);
                if (indexes.Count == 0 || indexes.Any(x => x < 1 || x > context.DisplayedTasks.Count)) return Clarify(CandidateRangeMessage() + " 변경된 업무는 없습니다.");
                foreach (int index in indexes)
                {
                    DisplayedTaskContext target = context.DisplayedTasks.FirstOrDefault(x => x.DisplayNumber == index); if (target == null) return Clarify(CandidateRangeMessage() + " 변경된 업무는 없습니다.");
                    string existing; if (planned.TryGetValue(target.TaskId, out existing) && existing != tool) return Clarify("CONFLICTING_ACTIONS: " + index + "번 업무에 서로 다른 상태가 지정되었습니다. 변경된 업무는 없습니다.");
                    if (!planned.ContainsKey(target.TaskId)) { planned[target.TaskId] = tool; decision.Calls.Add(Call(tool, "taskId", target.TaskId.ToString())); }
                }
            }
            if (decision.Calls.Count < 2) return null;
            logger.Info("Multi Action Parser", "actions=" + string.Join(",", decision.Calls.Select(x => x.Tool + ":" + Value(x, "taskId"))) + ",validation=PASS");
            return decision;
        }
        private static string MultiActionTool(string status) { string value = Regex.Replace(status ?? "", "\\s+", ""); if (Regex.IsMatch(value, "완료|끝|Done", RegexOptions.IgnoreCase)) return "complete_task"; if (Regex.IsMatch(value, "진행중|하는중|작업중", RegexOptions.IgnoreCase)) return "start_task"; if (Regex.IsMatch(value, "보류|막힘|대기|Blocked", RegexOptions.IgnoreCase)) return "block_task"; if (Regex.IsMatch(value, "Todo|시작전|해야함", RegexOptions.IgnoreCase)) return "reopen_task"; return null; }

        private async Task<AgentDecision> BuildNamedMultiActionDecisionAsync(string input)
        {
            string text = input ?? ""; MatchCollection statuses = Regex.Matches(text, "완료|끝났|끝내|끝난|Done|진행\\s*중|하는\\s*중|작업\\s*중|보류|막힘|대기|Blocked|Todo|시작\\s*전|해야\\s*함", RegexOptions.IgnoreCase); if (statuses.Count < 2) return null;
            IReadOnlyList<WorkTask> all = await tasks.GetAllAsync(); HashSet<Guid> displayed = new HashSet<Guid>(context.DisplayedTasks.Select(x => x.TaskId)); List<WorkTask> candidates = all.Where(x => displayed.Contains(x.Id)).ToList(); if (candidates.Count == 0) return null;
            AgentDecision decision = new AgentDecision { Type = AgentDecisionType.Write }; Dictionary<Guid, string> planned = new Dictionary<Guid, string>(); int start = 0;
            foreach (Match status in statuses)
            {
                string segment = text.Substring(start, status.Index - start); start = status.Index + status.Length; string tool = MultiActionTool(status.Value); WorkTask best = null; int bestScore = 0; bool tied = false;
                foreach (WorkTask candidate in candidates)
                {
                    int score = Regex.Matches(candidate.Title ?? "", "[A-Za-z0-9]+|[가-힣]{2,}").Cast<Match>().Select(x => x.Value).Where(x => x != "업무" && x != "작업").Where(x => segment.IndexOf(x, StringComparison.OrdinalIgnoreCase) >= 0).Select(x => x.Length).DefaultIfEmpty(0).Max();
                    if (score > bestScore) { best = candidate; bestScore = score; tied = false; } else if (score > 0 && score == bestScore) tied = true;
                }
                if (best == null || tied || tool == null) return Clarify("여러 업무 중 일부 대상을 정확히 특정하지 못했습니다. 변경된 업무는 없습니다.");
                string existing; if (planned.TryGetValue(best.Id, out existing) && existing != tool) return Clarify("CONFLICTING_ACTIONS: 같은 업무에 서로 다른 상태가 지정되었습니다. 변경된 업무는 없습니다.");
                if (!planned.ContainsKey(best.Id)) { planned[best.Id] = tool; decision.Calls.Add(Call(tool, "taskId", best.Id.ToString())); }
            }
            if (decision.Calls.Count < 2) return Clarify("서로 다른 업무별 상태를 확인하지 못했습니다. 변경된 업무는 없습니다."); logger.Info("Multi Action Parser", "namedActions=" + string.Join(",", decision.Calls.Select(x => x.Tool + ":" + Value(x, "taskId"))) + ",validation=PASS"); return decision;
        }

        private async Task<AgentDecision> ValidateMultiActionDecisionAsync(AgentDecision decision)
        {
            if (decision == null || decision.Type != AgentDecisionType.Write) return decision;
            IReadOnlyList<WorkTask> all = await tasks.GetAllAsync(); HashSet<Guid> existing = new HashSet<Guid>(all.Select(x => x.Id));
            foreach (AgentToolCall call in decision.Calls) { Guid id; if (!Guid.TryParse(Value(call, "taskId"), out id) || !existing.Contains(id)) return Clarify("여러 업무 중 일부 대상을 찾지 못했습니다. 변경된 업무는 없습니다."); }
            return decision;
        }

        private AgentDecision BuildReadDecision(string input)
        {
            string normalized = Normalize(input); bool workspaceOverview=IsCurrentWorkspaceOverviewRequest(input); AgentToolCall call;
            if (Contains(normalized, "방금", "아까", "최근", "마지막")) { call = Call("get_recent_tasks", "count", ExtractLimit(input, 1).ToString()); if (Contains(normalized, "내용", "설명", "본문")) call.Arguments["includeDescription"] = "true"; LogParsedQuery(call); return Read(call); }
            call = Call("search_tasks");
            if(workspaceOverview)call.Arguments["queryLabel"]="현재 Workspace 전체 업무 현황";
            string parsedStatus = NormalizeStatus(input); if (!string.IsNullOrWhiteSpace(parsedStatus)) call.Arguments["status"] = parsedStatus;
            TaskPriority parsedPriority; string priorityLabel; if(TryPriority(input,out parsedPriority,out priorityLabel))call.Arguments["priority"]=parsedPriority.ToString();
            if(!workspaceOverview)ApplyDateSemantics(input, call);
            string keyword = workspaceOverview?null:ExtractReadKeyword(input); if(call.Arguments.ContainsKey("priority"))keyword=Regex.Replace(keyword??"","(긴급|최우선|급함|높음|높은|중요한?|낮음|낮은|안\\s*급함|보통|일반|기본|중|것)"," ",RegexOptions.IgnoreCase).Trim(); if (!string.IsNullOrWhiteSpace(keyword)) call.Arguments["query"] = keyword;
            int limit = ExtractLimit(input, 0); if (limit > 0) call.Arguments["limit"] = limit.ToString();
            if (Contains(normalized, "등록 시간", "등록시간", "생성 시간", "언제 등록")) call.Arguments["includeCreatedAt"] = "true";
            LogParsedQuery(call);
            return Read(call);
        }
        private void LogParsedQuery(AgentToolCall call) { logger.Info("Parsed Query", string.Join(",", call.Arguments.Select(x => x.Key + "=" + x.Value))); logger.Info("Parsed Status", Value(call, "status") ?? "none"); logger.Info("Parsed Keyword", Value(call, "query") ?? "none"); logger.Info("Parsed Date Range", Value(call, "completedDate") ?? Value(call, "createdDate") ?? Value(call, "dueDate") ?? "none"); }

        private void ApplyDateSemantics(string input, AgentToolCall call)
        {
            string text = Normalize(input); TaskDateField type; string label; bool transitional = false; DateRange range;
            if (Contains(text, "등록한", "등록된", "만든", "생성한", "추가한")) { type = TaskDateField.Created; label = DateWord(text) + " 등록한 업무"; }
            else if (Contains(text, "완료한", "끝낸", "끝난")) { type = TaskDateField.Completed; label = DateWord(text) + " 완료한 업무"; call.Arguments["status"] = "Done"; call.Arguments["statusMode"] = "Exact"; }
            else { type = TaskDateField.Due; bool remaining = Regex.IsMatch(text, "(할 ?일|해야 ?할|해야 ?하는|남은 ?(업무|일|거|것))"); bool explicitDue = remaining || Contains(text, "할 업무", "할거", "할 거", "예정"); label = DateWord(text) + (remaining ? " 남은 할 일" : explicitDue ? " 예정된 업무" : " 업무"); if (remaining) { call.Arguments.Remove("status"); call.Arguments["statusMode"] = "NotDone"; } transitional = Contains(text, "오늘", "today") && !explicitDue; }
            if (!new DateExpressionParser().TryParse(text, clock.Now, out range)) return;
            call.Arguments["dateType"] = type.ToString(); call.Arguments["dateStart"] = range.StartDate.ToString("o"); call.Arguments["dateEnd"] = range.EndDate.AddDays(1).ToString("o"); call.Arguments["queryLabel"] = label.Trim(); if (transitional) call.Arguments["transitionalToday"] = "true";
            logger.Info("DateSemantic", "meaning=" + type + ",range=" + DateWord(text) + ",start=" + call.Arguments["dateStart"] + ",endExclusive=" + call.Arguments["dateEnd"] + ",repositoryFilter=" + type + ",fallback=" + (transitional ? "DATE_FALLBACK_CREATED_TODAY_ALLOWED" : "NO"));
        }
        private static string DateWord(string value) { if ((value ?? "").Contains("내일")) return "내일"; if ((value ?? "").Contains("어제")) return "어제"; if ((value ?? "").Contains("이번 주") || (value ?? "").Contains("이번주")) return "이번 주"; return "오늘"; }
        private static int ExtractLimit(string input, int fallback) { Match match = Regex.Match(input ?? "", "(\\d+)\\s*(?:개|건)"); int value; return match.Success && int.TryParse(match.Groups[1].Value, out value) ? Math.Max(1, value) : fallback; }
        private async Task<AgentDecision> BuildClassifiedDecisionAsync(LocalIntent intent, string input)
        {
            IntentEvidence evidence = safety.Evaluate(input); if (evidence.HasReadEvidence || IsStatusQuestion(input)) return BuildReadDecision(input); if ((intent == LocalIntent.StartTask && !IsStatusWriteRequest(input, "start_task")) || (intent == LocalIntent.CompleteTask && !IsStatusWriteRequest(input, "complete_task")) || (intent == LocalIntent.BlockTask && !IsStatusWriteRequest(input, "block_task"))) return Clarify("상태를 조회할지 변경할지 조금만 더 구체적으로 말씀해 주세요."); if (intent == LocalIntent.CreateTask && !evidence.HasCreateEvidence) return Clarify("새 업무를 등록하려는 요청인가요? 등록할 제목을 명확하게 말씀해 주세요."); if (intent == LocalIntent.DeleteTask && !evidence.HasDeleteEvidence) return Clarify("삭제할 대상을 명확하게 말씀해 주세요."); if (intent == LocalIntent.StartTask && !evidence.HasStartEvidence) return Clarify("해당 업무를 시작 상태로 변경할까요?"); if (intent == LocalIntent.CompleteTask && !evidence.HasCompleteEvidence) return Clarify("해당 업무를 완료 상태로 변경할까요?");
            string normalized = Normalize(input); if (intent == LocalIntent.ClearConversation) return Message("대화 기록을 비우겠습니다."); if (intent == LocalIntent.General) return Message("업무 등록과 상태 관리, 메모와 이력 조회, GitHub Issue 및 Project 연동을 도와드릴 수 있습니다."); if (intent == LocalIntent.ReadTask) return Contains(normalized, "방금", "아까", "최근", "마지막") ? Read(Call("get_recent_tasks", "count", "1")) : Read(Call("get_today_tasks")); if (intent == LocalIntent.History) return Read(Call("get_recent_history", "date", normalized.Contains("어제") ? clock.Now.Date.AddDays(-1).ToString("yyyy-MM-dd") : clock.Now.Date.ToString("yyyy-MM-dd"))); if (intent == LocalIntent.Briefing) return Multi(Call("get_today_tasks"), Call("get_recent_history", "date", clock.Now.Date.ToString("yyyy-MM-dd"))); if (intent == LocalIntent.GitHubQuery) return IsPronounReference(input) || context.LastReferencedTaskId.HasValue ? WriteOrRead(await ResolveTaskCallAsync("get_task_github_status", input), false) : Read(Call("refresh_github_issues")); if (intent == LocalIntent.GitHubImport) { int? issue = context.LastReferencedGitHubIssueNumber ?? context.LastCreatedGitHubIssueNumber; return issue.HasValue ? Write(Call("import_github_issue", "issueNumber", issue.Value.ToString())) : Clarify("가져올 GitHub Issue 번호를 알려주세요."); } if (intent == LocalIntent.DeleteTask) return await BuildDeletePreviewDecisionAsync(normalized); if (intent == LocalIntent.AddMemo) return IsDescriptionRequest(input) ? await BuildDescriptionDecisionAsync(input) : await BuildMemoDecisionAsync(input); if (intent == LocalIntent.CreateTask) return BuildCreateDecision(input); if (intent == LocalIntent.StartTask) return WriteOrRead(await ResolveTaskCallAsync("start_task", input), true); if (intent == LocalIntent.CompleteTask) return WriteOrRead(await ResolveTaskCallAsync("complete_task", input), true); if (intent == LocalIntent.BlockTask) return WriteOrRead(await ResolveTaskCallAsync("block_task", input), true); if (intent == LocalIntent.UpdateTask) return IsDescriptionRequest(input) ? await BuildDescriptionDecisionAsync(input) : Clarify("어떤 업무의 제목, 설명, 일정 또는 우선순위를 어떻게 변경할까요?"); return null;
        }
        private async Task<AgentDecision> BuildSafeDecisionAsync(string input)
        {
            string text = (input ?? "").Trim(); string normalized = Normalize(text);
            if (Regex.IsMatch(text, "^(안녕|안녕하세요)[.!? ]*$")) return Message("안녕하세요. 오늘 업무 정리부터 도와드릴까요?");
            if (Contains(normalized, "뭘 할 수", "뭐 할 수", "무엇을 할 수")) return Message("업무 등록과 상태 관리, 메모 기록, 오늘 업무와 활동 이력 조회, GitHub Issue 생성·조회·동기화, Project 상태 관리를 도와드릴 수 있습니다.");
            if (normalized.Contains("정신없")) return Message("많이 바쁘시겠네요. 원하시면 오늘 남은 업무와 진행 상황부터 정리해드릴게요.");
            if (IsBriefing(normalized)) return Multi(Call("get_today_tasks"), Call("get_recent_history", "date", clock.Now.Date.ToString("yyyy-MM-dd")));
            if (IsTodayQuestion(normalized)) return Read(Call("get_today_tasks"));
            if (Contains(normalized, "진행중인 거", "진행 중인 거", "진행중 업무")) return Read(Call("search_tasks", "status", "InProgress"));
            if (Contains(normalized, "완료한 건", "완료 업무")) return Read(Call("search_tasks", "status", "Done"));
            if (Contains(normalized, "방금 등록한", "아까 내가 뭐 등록", "최근 등록")) return Read(Call("get_recent_tasks", "count", "1"));
            if (Contains(normalized, "어제 뭐", "어제 내가 뭐")) return Read(Call("get_recent_history", "date", clock.Now.Date.AddDays(-1).ToString("yyyy-MM-dd")));
            if (IsGitHubRefresh(normalized)) return Read(Call("refresh_github_issues"));
            if (Contains(normalized, "로컬에도 가져", "업무로 가져", "슬레이브스플릿에 가져")) { int? issue = context.LastReferencedGitHubIssueNumber ?? context.LastCreatedGitHubIssueNumber; if (!issue.HasValue) return Clarify("가져올 GitHub Issue 번호를 알려주세요."); return Write(Call("import_github_issue", "issueNumber", issue.Value.ToString())); }
            if (IsDeleteRequest(normalized)) return await BuildDeletePreviewDecisionAsync(normalized);
            if (IsMemoRequest(normalized)) return await BuildMemoDecisionAsync(text);
            if (IsGitHubStatusQuestion(normalized)) return WriteOrRead(await ResolveTaskCallAsync("get_task_github_status", text), false);
            if (IsCreateRequest(normalized)) return BuildCreateDecision(text);
            if (Contains(normalized, "시작했", "시작할게", "진행 시작")) return WriteOrRead(await ResolveTaskCallAsync("start_task", text), true);
            if (Contains(normalized, "완료", "끝났", "끝냈", "다 했")) return WriteOrRead(await ResolveTaskCallAsync("complete_task", text), true);
            if (Contains(normalized, "다시 열", "reopen")) return WriteOrRead(await ResolveTaskCallAsync("reopen_task", text), true);
            if (Contains(normalized, "막혔", "대기 상태", "blocked")) return WriteOrRead(await ResolveTaskCallAsync("block_task", text), true);
            return Clarify("업무를 조회할지, 등록·변경할지 조금만 더 구체적으로 말씀해 주세요. 일반적인 질문도 편하게 물어보셔도 됩니다.");
        }
        private async Task<AgentDecision> BuildDeletePreviewDecisionAsync(string normalized)
        {
            IReadOnlyList<WorkTask> all = await tasks.GetAllAsync(); IEnumerable<WorkTask> candidates = all;
            if (Contains(normalized, "아까 완료") && context.LastCompletedTaskId.HasValue) { WorkTask recentCompleted = all.FirstOrDefault(x => x.Id == context.LastCompletedTaskId.Value); if (recentCompleted != null) { PendingAgentAction recentPending = new PendingAgentAction { ActionType = PendingAgentActionType.DeleteTasks, Need = PendingAgentNeed.Confirmation, CreatedAt = clock.Now, TargetTaskIds = new List<Guid> { recentCompleted.Id } }; context.SetPending(recentPending); return Clarify(BuildDeletePreview(new List<WorkTask> { recentCompleted })); } }
            if (IsPronounReference(normalized)) { Guid? contextId = Contains(normalized, "방금 완료", "최근 완료", "마지막 완료") ? context.LastCompletedTaskId : context.LastCreatedTaskId ?? context.LastModifiedTaskId ?? context.LastReferencedTaskId; WorkTask referenced = contextId.HasValue ? all.FirstOrDefault(x => x.Id == contextId.Value) : null; if (referenced != null) { PendingAgentAction contextPending = new PendingAgentAction { ActionType = PendingAgentActionType.DeleteTasks, Need = PendingAgentNeed.Confirmation, CreatedAt = clock.Now, TargetTaskIds = new List<Guid> { referenced.Id } }; context.SetPending(contextPending); context.RecordRead(contextPending.TargetTaskIds); return Clarify(BuildDeletePreview(new List<WorkTask> { referenced })); } }
