        private async Task<AgentResponse> HandlePendingAsync(string input)
        {
            PendingAgentAction pending = context.PendingAction; if (pending == null) return null; if ((clock.Now - pending.CreatedAt).TotalMinutes > 30) { context.ClearPending(); return null; }
            if (IsCancel(input)) { context.ClearPending(); return Response(true, "취소했습니다. 변경된 업무는 없습니다.", null); }
            if (pending.Need == PendingAgentNeed.Confirmation && !IsConfirm(input)) { IntentEvidence evidence = safety.Evaluate(input); if (evidence.HasReadEvidence || IsLikelyTaskRead(input)) { logger.Info("Confirmation Result", "new-intent; pending cancelled"); context.ClearPending(); return null; } }
            if (pending.ActionType == PendingAgentActionType.ChangeStatus && pending.Need == PendingAgentNeed.Target)
            {
                List<int> requested = ExtractCandidateIndexes(input); if (requested.Any(x => x < 1 || x > context.DisplayedTasks.Count)) return Response(false, CandidateRangeMessage(), null);
                IReadOnlyList<Guid> targets = ResolveCandidateReferences(input); if (targets.Count == 0) { IntentEvidence evidence = safety.Evaluate(input); if (evidence.HasReadEvidence) { context.ClearPending(); return null; } return Response(false, "현재 목록에서 처리할 업무 번호를 알려주세요. 예: '2번 3번', '마지막거', '전체 다'", null); }
                string tool; pending.Arguments.TryGetValue("tool", out tool); context.ClearPending(); AgentDecision change = new AgentDecision { Type = AgentDecisionType.Write }; foreach (Guid target in targets) change.Calls.Add(Call(tool, "taskId", target.ToString())); logger.Info("Resolved Targets", string.Join(",", targets)); return await ExecuteDecisionAsync(change, input, false);
            }
            if (pending.ActionType == PendingAgentActionType.AddMemo) { if (IsConfirm(input)) return Response(false, "메모 내용을 말씀해 주세요.", pending.TargetTaskIds.FirstOrDefault()); Guid id = pending.TargetTaskIds.FirstOrDefault(); context.ClearPending(); AgentToolCall memo = Call("add_task_memo", "taskId", id.ToString()); memo.Arguments["memo"] = input.Trim(); return await ExecuteDecisionAsync(Write(memo), input, false); }
            if (pending.ActionType == PendingAgentActionType.UpdateDescription) { if (pending.Need == PendingAgentNeed.Target) { Guid? target = await ResolveContextTaskAsync(input); if (!target.HasValue) return Response(false, "변경할 업무를 찾지 못했습니다. 제목이나 '방금 만든 업무'처럼 말씀해 주세요.", null); string saved; pending.Arguments.TryGetValue("description", out saved); if (string.IsNullOrWhiteSpace(saved)) { pending.TargetTaskIds = new List<Guid> { target.Value }; pending.Need = PendingAgentNeed.Content; return Response(false, "어떤 내용으로 업무 설명을 변경할까요?", target); } context.ClearPending(); AgentToolCall targeted = Call("update_task_description", "taskId", target.Value.ToString()); targeted.Arguments["description"] = saved; return await ExecuteDecisionAsync(Write(targeted), input, false); } if (IsConfirm(input)) return Response(false, "변경할 업무 설명을 말씀해 주세요.", pending.TargetTaskIds.FirstOrDefault()); Guid id = pending.TargetTaskIds.FirstOrDefault(); context.ClearPending(); AgentToolCall update = Call("update_task_description", "taskId", id.ToString()); update.Arguments["description"] = input.Trim(); return await ExecuteDecisionAsync(Write(update), input, false); }
            if (pending.ActionType == PendingAgentActionType.CreateTask) { if (!IsConfirm(input)) return Response(false, "등록하려면 확인해 주세요. 취소하려면 '취소'라고 말씀해 주세요.", null); context.ClearPending(); AgentToolCall create = Call("create_task", "title", pending.Arguments["title"]); string description, dueDate; if (pending.Arguments.TryGetValue("description", out description) && !string.IsNullOrWhiteSpace(description)) create.Arguments["description"] = description; if (pending.Arguments.TryGetValue("dueDate", out dueDate) && !string.IsNullOrWhiteSpace(dueDate)) create.Arguments["dueDate"] = dueDate; return await ExecuteDecisionAsync(Write(create), input, false); }
            if (!IsConfirm(input)) return Response(false, "진행하려면 확인해 주세요. 취소하려면 '취소'라고 말씀해 주세요.", null);
            logger.Info("Confirmation Result", "confirmed:" + pending.ActionType);
            if (pending.ActionType == PendingAgentActionType.ChangeStatus && pending.Need == PendingAgentNeed.Confirmation) { string tool; pending.Arguments.TryGetValue("tool", out tool); context.ClearPending(); AgentDecision bulk = new AgentDecision { Type = AgentDecisionType.Write }; foreach (Guid id in pending.TargetTaskIds) bulk.Calls.Add(Call(tool, "taskId", id.ToString())); return await ExecuteDecisionAsync(bulk, input, false); }
            context.ClearPending(); if (pending.ActionType == PendingAgentActionType.DeleteTasks) { AgentToolCall delete = Call("delete_tasks", "taskIds", string.Join(",", pending.TargetTaskIds)); AgentToolResult result = await executor.ExecuteAsync(delete, CancellationToken.None); if (result.Success) foreach (Guid id in pending.TargetTaskIds) context.RecordDeleted(id); return Response(result.Success, result.Success ? result.Message : (result.SafeErrorMessage ?? result.Message), result.TaskId); }
            return null;
        }
        private sealed class HybridExecution { public AgentDecision Decision; public AgentResponse BlockedResponse; public HybridCommandResult Hybrid; public IList<Guid> ResolvedTaskIds = new List<Guid>(); public string SafetyResult = "PASS"; }

        private async Task<HybridExecution> ApplyHybridAsync(string input, AgentDecision parserDecision)
        {
            HybridExecution bridge = new HybridExecution { Decision = parserDecision }; AgentDryRunResult snapshot = Snapshot(parserDecision);
            if(parserDecision!=null&&parserDecision.Type==AgentDecisionType.Clarification)return bridge;
            if (IsDueDateUpdateRequest(input) && parserDecision != null && parserDecision.Type == AgentDecisionType.Clarification) { bridge.SafetyResult = (parserDecision.Content ?? "").StartsWith("INVALID_DATE") ? "INVALID_DATE" : (parserDecision.Content ?? "").StartsWith("AMBIGUOUS_TARGET") ? "AMBIGUOUS_TARGET" : "TARGET_NOT_FOUND"; return bridge; }
            if (IsDueDateUpdateRequest(input) && parserDecision != null && parserDecision.Type == AgentDecisionType.Write && parserDecision.Calls.All(x => x.Tool == "update_task_due_date")) return bridge;
            if (IsPriorityUpdateRequest(input) && parserDecision != null && parserDecision.Type == AgentDecisionType.Clarification) { bridge.SafetyResult=(parserDecision.Content??"").StartsWith("AMBIGUOUS")?"AMBIGUOUS_TARGET":"TARGET_NOT_FOUND";return bridge; }
            if (IsPriorityUpdateRequest(input) && parserDecision != null && parserDecision.Type == AgentDecisionType.Write && parserDecision.Calls.All(x=>x.Tool=="update_task_priority"))return bridge;
            if (IsPotentialStatusMultiAction(input) && parserDecision != null && parserDecision.Type == AgentDecisionType.Clarification) { bridge.SafetyResult = (parserDecision.Content ?? "").Contains("CONFLICTING_ACTIONS") ? "CONFLICTING_ACTIONS" : "MULTI_ACTION_VALIDATION_FAILED"; return bridge; }
            string fallbackReason = HybridCommandInterpreter.GetFallbackReason(input, snapshot);
            if (!localLlmSettings.Enabled && fallbackReason != null) { bridge.SafetyResult = "BLOCKED_LOCAL_AI_DISABLED"; bridge.BlockedResponse = Response(false, "자연어 해석이 필요한 명령인데 Local AI가 비활성화되어 있습니다.", null); return bridge; }
            if (!localLlmSettings.Enabled) return bridge;
            IReadOnlyList<WorkTask> all = await tasks.GetAllAsync(); Dictionary<Guid, WorkTask> byId = all.ToDictionary(x => x.Id); List<WorkTask> candidates = context.DisplayedTasks.OrderBy(x => x.DisplayNumber).Where(x => byId.ContainsKey(x.TaskId)).Select(x => byId[x.TaskId]).ToList();
            string candidateText = string.Join("\n", candidates.Select((x, i) => (i + 1) + ". " + x.Title + " - " + x.Status));
            using (CancellationTokenSource timeout = new CancellationTokenSource(TimeSpan.FromSeconds(hybridTimeoutSeconds)))
                bridge.Hybrid = await hybridInterpreter.InterpretParsedAsync(input, snapshot, candidates, candidateText, localLlmSettings.EffectiveModel, timeout.Token);
            if (bridge.Hybrid.MultiActionSchemaLimit) { bridge.SafetyResult = "MULTI_ACTION_SCHEMA_LIMIT"; bridge.BlockedResponse = Response(false, "한 문장에 서로 다른 업무 변경이 포함되어 있습니다. 업무별로 나누어 말씀해 주세요.", null); return bridge; }
            if (!bridge.Hybrid.FallbackCalled) return bridge;
            logger.Info("HybridCommand", "source=" + bridge.Hybrid.Source + ",fallback=true,reason=" + bridge.Hybrid.Reason + ",latency=" + bridge.Hybrid.HybridLatencyMs + "ms"); if (bridge.Hybrid.LlmResponse != null) logger.Info("LocalAI", "enabled=" + localLlmSettings.Enabled + ",endpoint=" + localLlmSettings.Endpoint + ",model=" + localLlmSettings.EffectiveModel + ",online=" + string.IsNullOrWhiteSpace(bridge.Hybrid.LlmResponse.FailureKind) + ",failure=" + (bridge.Hybrid.LlmResponse.FailureKind ?? "none"));
            if (bridge.Hybrid.Source == HybridCommandSource.UNRESOLVED)
            {
                bridge.SafetyResult = bridge.Hybrid.MultiActionSchemaLimit ? "MULTI_ACTION_SCHEMA_LIMIT" : "UNRESOLVED";
                string message = bridge.Hybrid.MultiActionSchemaLimit ? "한 문장에 서로 다른 업무 변경이 포함되어 있습니다. 업무별로 나누어 말씀해 주세요." : IsLlmUnavailable(bridge.Hybrid) ? "자연어 해석이 필요한 명령인데 Local AI를 사용할 수 없습니다." : "어떤 업무를 말씀하시는지 특정하지 못했습니다.";
                bridge.BlockedResponse = Response(false, message, null); return bridge;
            }
            if (bridge.Hybrid.Source != HybridCommandSource.LLM) return bridge;
            AgentDecision translated = TranslateHybrid(input, bridge.Hybrid.Result, all, bridge); if (translated == null && bridge.BlockedResponse == null) bridge.BlockedResponse = Response(false, "어떤 업무를 말씀하시는지 특정하지 못했습니다.", null); else bridge.Decision = translated; return bridge;
        }

        private AgentDryRunResult Snapshot(AgentDecision decision)
        {
            AgentDryRunResult result = new AgentDryRunResult { DecisionType = decision == null ? "Invalid" : decision.Type.ToString(), Path = "AgentConversationService:Parser>Hybrid", FailureReason = decision == null || decision.Type == AgentDecisionType.Clarification || decision.Type == AgentDecisionType.Invalid ? "UNRESOLVED" : null };
            IList<AgentToolCall> calls = decision == null ? new List<AgentToolCall>() : decision.Calls; string[] names = calls.Select(x => x.Tool).ToArray();
            if (names.Any(x => x == "create_task")) result.Intent = "CREATE_TASK"; else if (names.Any(IsTargetWrite) || names.Any(x => x == "update_task_description" || x == "add_task_memo")) result.Intent = "UPDATE_TASK"; else if (names.Any(x => x == "delete_task" || x == "delete_tasks")) result.Intent = "DELETE_TASK"; else if (decision != null && (decision.Type == AgentDecisionType.Read || names.Any())) result.Intent = "READ_TASK"; else result.Intent = "UNKNOWN";
            if (names.Any(x => x == "complete_task")) result.Status = "Done"; else if (names.Any(x => x == "start_task")) result.Status = "InProgress"; else if (names.Any(x => x == "block_task")) result.Status = "Blocked"; else if (names.Any(x => x == "reopen_task")) result.Status = "Todo";
            foreach (AgentToolCall call in calls) { Guid id; if (!Guid.TryParse(Value(call, "taskId"), out id)) continue; DisplayedTaskContext shown = context.DisplayedTasks.FirstOrDefault(x => x.TaskId == id); if (shown != null) result.TargetIndexes.Add(shown.DisplayNumber); }
            result.TargetKeyword = calls.Select(x => Value(x, "query")).FirstOrDefault(x => !string.IsNullOrWhiteSpace(x)); result.Title = calls.Where(x => x.Tool == "create_task").Select(x => Value(x, "title")).FirstOrDefault(); result.DueDate = calls.Where(x => x.Tool == "create_task").Select(x => Value(x, "dueDate")).FirstOrDefault(); return result;
        }

        private AgentDecision TranslateHybrid(string input, LlmTaskParseResult command, IReadOnlyList<WorkTask> all, HybridExecution bridge)
        {
            if (command == null || command.Intent == "UNKNOWN") return null;
            if (command.Intent == "CREATE_TASK") { AgentToolCall create = Call("create_task", "title", command.Title); if (!string.IsNullOrWhiteSpace(command.DueDate)) create.Arguments["dueDate"] = command.DueDate; return Write(create); }
            if (command.Intent == "READ_TASK") { if (!string.IsNullOrWhiteSpace(command.TargetKeyword)) return Read(Call("search_tasks", "query", command.TargetKeyword)); return BuildReadDecision(input); }
            if (command.Intent == "UPDATE_TASKS")
            {
                Dictionary<Guid, string> planned = new Dictionary<Guid, string>(); AgentDecision multi = new AgentDecision { Type = AgentDecisionType.Write };
                foreach (LlmStatusAction action in command.Actions ?? new List<LlmStatusAction>())
                {
                    List<Guid> actionTargets = context.ResolveMany(action.TargetIndexes).ToList(); if (actionTargets.Count == 0 && !string.IsNullOrWhiteSpace(action.TargetKeyword)) { List<WorkTask> matching = all.Where(x => (x.Title ?? "").IndexOf(action.TargetKeyword, StringComparison.OrdinalIgnoreCase) >= 0).ToList(); if (matching.Count == 1) actionTargets.Add(matching[0].Id); }
                    string actionTool = action.Status == "Done" ? "complete_task" : action.Status == "InProgress" ? "start_task" : action.Status == "Blocked" ? "block_task" : action.Status == "Todo" ? "reopen_task" : null; if (actionTool == null || actionTargets.Count == 0) { bridge.SafetyResult = "MULTI_ACTION_VALIDATION_FAILED"; bridge.BlockedResponse = Response(false, "여러 업무 중 일부 대상을 정확히 특정하지 못했습니다. 변경된 업무는 없습니다.", null); return null; }
                    foreach (Guid id in actionTargets) { string existing; if (planned.TryGetValue(id, out existing) && existing != actionTool) { bridge.SafetyResult = "CONFLICTING_ACTIONS"; bridge.BlockedResponse = Response(false, "CONFLICTING_ACTIONS: 같은 업무에 서로 다른 상태가 지정되었습니다. 변경된 업무는 없습니다.", null); return null; } if (!planned.ContainsKey(id)) { planned[id] = actionTool; multi.Calls.Add(Call(actionTool, "taskId", id.ToString())); } }
                }
                if (multi.Calls.Count == 0) return null; bridge.ResolvedTaskIds = planned.Keys.ToList(); return multi;
            }
            List<Guid> targets = context.ResolveMany(command.TargetIndexes).ToList();
            if (targets.Count == 0 && command.Reference == "LAST_CREATED" && context.LastCreatedTaskId.HasValue) targets.Add(context.LastCreatedTaskId.Value);
            if (targets.Count == 0 && command.Reference == "LAST_MENTIONED" && context.LastReferencedTaskId.HasValue) targets.Add(context.LastReferencedTaskId.Value);
            if (targets.Count == 0 && !string.IsNullOrWhiteSpace(command.TargetKeyword)) { List<WorkTask> matching = all.Where(x => (x.Title ?? "").IndexOf(command.TargetKeyword, StringComparison.OrdinalIgnoreCase) >= 0).ToList(); if (matching.Count == 1) targets.Add(matching[0].Id); }
            if (targets.Count == 0) return null; bridge.ResolvedTaskIds = targets;
            if (command.Intent == "DELETE_TASK") { List<WorkTask> values = all.Where(x => targets.Contains(x.Id)).ToList(); PendingAgentAction pending = new PendingAgentAction { ActionType = PendingAgentActionType.DeleteTasks, Need = PendingAgentNeed.Confirmation, CreatedAt = clock.Now, TargetTaskIds = targets }; context.SetPending(pending); bridge.SafetyResult = "DELETE_CONFIRMATION_REQUIRED"; bridge.BlockedResponse = Response(false, BuildDeletePreview(values), null); return null; }
            if (command.Intent != "UPDATE_TASK") return null; string tool = command.Status == "Done" ? "complete_task" : command.Status == "InProgress" ? "start_task" : command.Status == "Blocked" ? "block_task" : command.Status == "Todo" ? "reopen_task" : null; if (tool == null) return null;
            if (targets.Count > 1 && Regex.IsMatch(input ?? "", "전체|전부|모두|다\\s*(완료|끝)|싹")) { PendingAgentAction pending = new PendingAgentAction { ActionType = PendingAgentActionType.ChangeStatus, Need = PendingAgentNeed.Confirmation, CreatedAt = clock.Now, TargetTaskIds = targets }; pending.Arguments["tool"] = tool; context.SetPending(pending); bridge.SafetyResult = "BULK_UPDATE_CONFIRMATION_REQUIRED"; bridge.BlockedResponse = Response(false, targets.Count + "개 업무를 변경할까요? 진행하려면 확인해 주세요.", null); return null; }
            AgentDecision result = new AgentDecision { Type = AgentDecisionType.Write }; foreach (Guid id in targets) result.Calls.Add(Call(tool, "taskId", id.ToString())); return result;
        }

        private static bool IsLlmUnavailable(HybridCommandResult value) { string error = value == null || value.LlmResponse == null ? null : value.LlmResponse.Error; return !string.IsNullOrWhiteSpace(error); }
        private static bool IsPotentialStatusMultiAction(string input) { return Regex.Matches(input ?? "", "완료|끝났|끝내|끝난|Done|진행\\s*중|하는\\s*중|작업\\s*중|보류|막힘|대기|Blocked|Todo|시작\\s*전|해야\\s*함", RegexOptions.IgnoreCase).Count >= 2; }
        private static void ApplyInterpreterMetadata(AgentResponse response, HybridExecution bridge) { if (response == null || bridge == null || bridge.Hybrid == null) return; response.InterpreterSource = bridge.Hybrid.Source.ToString(); response.FallbackCalled = bridge.Hybrid.FallbackCalled; response.FallbackReason = bridge.Hybrid.Reason; response.LlmCalled = bridge.Hybrid.LlmResponse != null && bridge.Hybrid.FallbackCalled; response.LlmSuccess = response.LlmCalled && bridge.Hybrid.LlmResponse.Success; response.LlmFailureKind = response.LlmCalled ? bridge.Hybrid.LlmResponse.FailureKind : null; response.LlmRawOutput = response.LlmCalled ? bridge.Hybrid.LlmResponse.RawOutput : null; }

