        private void SaveHybridExecution(string input, HybridExecution bridge, AgentResponse response, long totalLatencyMs)
        {
            if (disablePersistentExecutionLog || bridge == null || bridge.Hybrid == null) return; try { string root = Environment.GetEnvironmentVariable("SLAVESPLIT_DATA_DIR") ?? System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "SlaveSplit"); string dir = System.IO.Path.Combine(root, "Task022"); System.IO.Directory.CreateDirectory(dir); string path = System.IO.Path.Combine(dir, "agent-hybrid-results.jsonl"); var record = new { Timestamp = DateTime.Now, Input = input, ParserResult = bridge.Hybrid.ParserResult, FallbackCalled = bridge.Hybrid.FallbackCalled, FallbackReason = bridge.Hybrid.Reason, LlmResult = bridge.Hybrid.LlmResponse == null ? null : bridge.Hybrid.LlmResponse.Result, HybridResult = bridge.Hybrid.Result, SelectedSource = bridge.Hybrid.Source.ToString(), ResolvedTaskIds = bridge.ResolvedTaskIds, SafetyResult = bridge.SafetyResult, ExecutionType = bridge.Decision == null ? "BLOCKED" : bridge.Decision.Type.ToString(), ExecutionResult = response == null ? null : response.Message, LatencyMs = totalLatencyMs }; System.IO.File.AppendAllText(path, Newtonsoft.Json.JsonConvert.SerializeObject(record) + Environment.NewLine); } catch (Exception ex) { logger.Error("Hybrid Log", ex); }
        }

        private async Task<AgentResponse> ExecuteDecisionAsync(AgentDecision decision, string original, bool fallbackUsed)
        {
            if (decision == null || decision.Type == AgentDecisionType.Invalid) return Response(false, "응답을 처리하지 못했습니다. 다시 말씀해 주세요.", null);
            if (decision.Type == AgentDecisionType.Message || decision.Type == AgentDecisionType.Clarification) return Response(decision.Type == AgentDecisionType.Message, decision.Content, null);
            List<AgentToolResult> results = new List<AgentToolResult>(); foreach (AgentToolCall call in decision.Calls) { AgentResponse safety = await PrepareCallAsync(call, original); if (safety != null) return safety; results.Add(await executor.ExecuteAsync(call, CancellationToken.None)); }
            return await ComposeResponseAsync(decision, results);
        }
        private async Task<AgentResponse> PrepareCallAsync(AgentToolCall call, string original)
        {
            if (call.Tool == "delete_task" || call.Tool == "delete_tasks") { AgentDecision preview = await BuildDeletePreviewDecisionAsync(Normalize(original)); return Response(false, preview.Content, null); }
            if (IsTargetWrite(call.Tool)) { Guid resolved; WorkTask existing = Guid.TryParse(Value(call, "taskId"), out resolved) ? await tasks.GetByIdAsync(resolved) : null; if (existing == null) { logger.Info("Safety Decision", "blocked: targetResolved=false,tool=" + call.Tool); return await AskForTargetAsync(); } logger.Info("Safety Decision", "allowed: targetResolved=true,targetCount=1,ambiguous=false,tool=" + call.Tool); }
            if (RequiresTask(call.Tool) && !call.Arguments.ContainsKey("taskId") && string.IsNullOrWhiteSpace(Value(call, "query"))) { Guid? id = await ResolveContextTaskAsync(original); if (!id.HasValue) return await AskForTargetAsync(); call.Arguments["taskId"] = id.Value.ToString(); }
            if (call.Tool == "add_task_memo" && string.IsNullOrWhiteSpace(Value(call, "memo"))) { Guid id; if (!Guid.TryParse(Value(call, "taskId"), out id)) return await AskForTargetAsync(); context.SetPending(new PendingAgentAction { ActionType = PendingAgentActionType.AddMemo, CreatedAt = clock.Now, TargetTaskIds = new List<Guid> { id } }); return Response(false, "어떤 내용을 메모로 추가할까요?", id); }
            return null;
        }
        private async Task<AgentResponse> ComposeResponseAsync(AgentDecision decision, IList<AgentToolResult> results)
        {
            logger.Info("Repository Result Count", string.Join(",", results.Select(x => x.Tool + "=" + (x.Tasks == null ? 0 : x.Tasks.Count))));
            if(results.Count==1&&results[0].Tool=="work_briefing"){AgentToolResult briefing=results[0];context.SetDisplayedTasks(briefing.Tasks,clock.Now);context.RecordRead(briefing.Tasks.Select(x=>x.Id));return Response(true,briefing.Message,null);}
            if (results.Count > 0 && results.All(x => x.Tool == "update_task_due_date")) return FormatDueDateUpdateResponse(results);
            if (results.Count > 0 && results.All(x => IsStatusUpdateTool(x.Tool)||x.Tool=="update_task_priority")) return FormatUpdateResponse(results);
            if (results.Count == 1) { AgentToolResult one = results[0]; if (!one.Success) return Response(false, one.SafeErrorMessage ?? one.Message, one.TaskId); if (one.Tool == "create_task" && one.TaskId.HasValue) { context.RecordCreated(one.TaskId.Value, one.Title); WorkTask reloaded = await tasks.GetByIdAsync(one.TaskId.Value); logger.Info("DateCreate", "entityDueDate=" + (reloaded == null || !reloaded.DueDate.HasValue ? "null" : reloaded.DueDate.Value.ToString("yyyy-MM-dd")) + ",savedDueDate=" + (reloaded == null || !reloaded.DueDate.HasValue ? "null" : reloaded.DueDate.Value.ToString("yyyy-MM-dd")) + ",reloadedDueDate=" + (reloaded == null || !reloaded.DueDate.HasValue ? "null" : reloaded.DueDate.Value.ToString("yyyy-MM-dd"))); } if (one.Tasks != null && one.Tasks.Count > 0) context.SetDisplayedTasks(one.Tasks, clock.Now); if (!string.IsNullOrWhiteSpace(one.DateFallback)) logger.Info("DateSemantic", one.DateFallback + ",resultCount=" + one.Tasks.Count); if (one.Tool == "get_today_tasks") { context.RecordTaskSummary(one.Tasks.Count(x => x.Status == WorkTaskStatus.Todo)); return Response(true, FormatToday(one.Tasks), null); } if (one.Tool == "get_recent_tasks") return Response(true, FormatRecent(one.Tasks, one.IncludeDescription), one.Tasks.FirstOrDefault() == null ? (Guid?)null : one.Tasks[0].Id); if (one.Tool == "search_tasks") { context.RecordTaskSummary(one.Tasks.Count(x => x.Status == WorkTaskStatus.Todo)); bool overview=(one.QueryLabel??"").Contains("전체 업무 현황");bool today=one.QueryLabel=="오늘 업무";return Response(true, overview?FormatStatusSummary("현재 Workspace 전체 업무 현황",one.Tasks):today?FormatStatusSummary("오늘 업무 현황",one.Tasks):FormatTasks(one.Tasks, one.IncludeCreatedAt, one.IncludeDescription, one.QueryLabel), one.Tasks.Count == 1 ? (Guid?)one.Tasks[0].Id : null); } if (one.Tool == "get_recent_history") return Response(true, await FormatHistoryAsync(one.History), null); if (one.Tool == "refresh_github_issues") return Response(true, FormatGitHubRefresh(one.Issues), null); return Response(true, one.Message, one.TaskId); }
            AgentToolResult todayResult = results.FirstOrDefault(x => x.Tool == "get_today_tasks"); AgentToolResult history = results.FirstOrDefault(x => x.Tool == "get_recent_history"); return Response(results.All(x => x.Success), await FormatBriefingAsync(todayResult, history), null);
        }
        private AgentResponse FormatUpdateResponse(IList<AgentToolResult> results)
        {
            List<AgentToolResult> succeeded = results.Where(x => x.Success).ToList(), failed = results.Where(x => !x.Success).ToList(); string action = UpdateAction(results.FirstOrDefault() == null ? null : results[0].Tool); StringBuilder text = new StringBuilder();
            if (results.Count == 1 && succeeded.Count == 1) text.Append(succeeded[0].Message);
            else if (failed.Count == 0 && results.Select(x => x.Tool).Distinct().Count() == 1) { text.Append(results.Count).Append("건의 업무를 ").Append(action).Append("했습니다.\n\n"); for (int i = 0; i < succeeded.Count; i++) text.Append(i + 1).Append(". ").Append(succeeded[i].Title).Append(i + 1 == succeeded.Count ? "" : "\n"); }
            else if (failed.Count == 0) { text.Append(results.Count).Append("건의 업무 상태를 변경했습니다.\n\n"); for (int i = 0; i < succeeded.Count; i++) text.Append(i + 1).Append(". ").Append(succeeded[i].Title).Append(" — ").Append(UpdateAction(succeeded[i].Tool)).Append(i + 1 == succeeded.Count ? "" : "\n"); }
            else { bool mixed = results.Select(x => x.Tool).Distinct().Count() > 1; text.Append(results.Count).Append("건 중 ").Append(succeeded.Count).Append(mixed ? "건의 상태를 변경했습니다." : "건을 " + action + "했습니다."); if (succeeded.Count > 0) { text.Append("\n\n성공:"); foreach (AgentToolResult item in succeeded) text.Append("\n- ").Append(item.Title).Append(mixed ? " — " + UpdateAction(item.Tool) : ""); } text.Append("\n\n실패:"); foreach (AgentToolResult item in failed) text.Append("\n- ").Append(item.Title ?? "대상 업무").Append(mixed ? " — " + UpdateAction(item.Tool) : "").Append("\n  사유: ").Append(item.SafeErrorMessage ?? item.Message ?? item.ErrorType ?? "알 수 없는 오류"); }
            List<AgentToolResult> syncIssues = succeeded.Where(HasGitHubSyncIssue).ToList(); if (syncIssues.Count > 0) text.Append("\n\n업무 변경은 저장했지만 GitHub 동기화가 완료되지 않은 업무가 ").Append(syncIssues.Count).Append("건 있습니다.");
            logger.Info("Execution", "intent=UPDATE_TASK,requested=" + results.Count + ",resolvedTaskIds=" + string.Join(",", results.Where(x => x.TaskId.HasValue).Select(x => x.TaskId.Value)) + ",success=" + succeeded.Count + ",failure=" + failed.Count + ",githubSyncIssues=" + syncIssues.Count + ",responseFormatter=UPDATE,summaryFormatterCalled=false");
            return Response(failed.Count == 0, text.ToString(), succeeded.Count == 1 ? succeeded[0].TaskId : null);
        }
        private static AgentResponse FormatDueDateUpdateResponse(IList<AgentToolResult> results) { List<AgentToolResult> success = results.Where(x => x.Success).ToList(); if (results.Count == 1) { AgentToolResult one = results[0]; return Response(one.Success, one.Success ? one.Message : one.SafeErrorMessage ?? one.Message, one.TaskId); } StringBuilder text = new StringBuilder().Append(success.Count).Append("건의 업무 일정을 "); string label = results.Select(x => x.Message).FirstOrDefault(x => !string.IsNullOrWhiteSpace(x)); if (!string.IsNullOrWhiteSpace(label) && label.Contains("내일")) text.Append("내일로 "); else if (!string.IsNullOrWhiteSpace(label) && label.Contains("오늘")) text.Append("오늘로 "); text.Append("변경했습니다.\n\n"); for (int i = 0; i < success.Count; i++) text.Append(i + 1).Append(". ").Append(success[i].Title).Append(i + 1 == success.Count ? "" : "\n"); return Response(success.Count == results.Count, text.ToString(), null); }
        private static bool IsStatusUpdateTool(string tool) { return tool == "complete_task" || tool == "start_task" || tool == "reopen_task" || tool == "block_task"; }
        private static string UpdateAction(string tool) { if (tool == "complete_task") return "완료"; if (tool == "start_task") return "진행 중으로 변경"; if (tool == "reopen_task") return "할 일로 변경"; if (tool == "block_task") return "대기 상태로 변경"; if(tool=="update_task_priority")return "우선순위 변경"; return "변경"; }
        private static bool HasGitHubSyncIssue(AgentToolResult value) { return value.GitHubSyncStatus == GitHubSyncStatus.Pending || value.GitHubSyncStatus == GitHubSyncStatus.Failed || value.GitHubProjectSyncStatus == GitHubSyncStatus.Pending || value.GitHubProjectSyncStatus == GitHubSyncStatus.Failed || !string.IsNullOrWhiteSpace(value.GitHubSyncError); }
        private async Task<AgentToolCall> ResolveTaskCallAsync(string tool, string input) { Guid? id = await ResolveContextTaskAsync(input); return id.HasValue ? Call(tool, "taskId", id.Value.ToString()) : Call(tool); }
        private async Task<AgentDecision> BuildStatusDecisionAsync(string tool, string input)
        {
            List<int> requested = ExtractCandidateIndexes(input); if (requested.Any(x => x < 1 || x > context.DisplayedTasks.Count)) { logger.Info("Candidate Resolution Result", "out-of-range"); return Clarify(CandidateRangeMessage()); }
            IReadOnlyList<Guid> references = ResolveCandidateReferences(input); if (references.Count > 0) { AgentDecision decision = new AgentDecision { Type = AgentDecisionType.Write }; foreach (Guid id in references) decision.Calls.Add(Call(tool, "taskId", id.ToString())); logger.Info("Resolved Targets", string.Join(",", references)); logger.Info("Target Confidence", "1.000;ambiguous=false"); return decision; }
            Guid? target = await ResolveContextTaskAsync(input); if (target.HasValue) return Write(Call(tool, "taskId", target.Value.ToString()));
            IReadOnlyList<WorkTask> all = await tasks.GetAllAsync(); List<WorkTask> candidates = all.Where(x => x.Status != WorkTaskStatus.Done).OrderByDescending(x => x.UpdatedAt).Take(5).ToList(); context.SetDisplayedTasks(candidates, clock.Now);
            PendingAgentAction pending = new PendingAgentAction { ActionType = PendingAgentActionType.ChangeStatus, Need = PendingAgentNeed.Target, CreatedAt = clock.Now }; pending.Arguments["tool"] = tool; context.SetPending(pending); logger.Info("Safety Decision", "blocked: unresolved write target"); return Clarify(FormatCandidates("어떤 업무를 " + (tool == "complete_task" ? "완료" : tool == "start_task" ? "진행 중" : "대기 상태") + "로 변경할까요?", candidates));
        }
        private IReadOnlyList<Guid> ResolveCandidateReferences(string input)
        {
            string text = Normalize(input); if (Regex.IsMatch(text, "(전체|전부)( 다)?")) return context.ResolveAll(); if (Regex.IsMatch(text, "마지막(거|것)?")) { Guid? last = context.ResolveLast(); return last.HasValue ? new List<Guid> { last.Value }.AsReadOnly() : new List<Guid>().AsReadOnly(); }
            return context.ResolveMany(ExtractCandidateIndexes(input));
        }
        private static List<int> ExtractCandidateIndexes(string input) { List<int> values = new List<int>(); string raw = input ?? ""; Match range = Regex.Match(raw, "(\\d+)\\s*번\\s*부터\\s*(\\d+)\\s*번\\s*까지"); if (range.Success) { int start = int.Parse(range.Groups[1].Value), end = int.Parse(range.Groups[2].Value); if (start <= end) for (int i = start; i <= end; i++) values.Add(i); else for (int i = start; i >= end; i--) values.Add(i); } foreach (Match match in Regex.Matches(raw, "(\\d+)\\s*번")) { int number = int.Parse(match.Groups[1].Value); if (!values.Contains(number)) values.Add(number); } if (Regex.IsMatch(raw, "\\d+\\s*번")) foreach (Match match in Regex.Matches(raw, "(\\d+)\\s*,")) { int number = int.Parse(match.Groups[1].Value); if (!values.Contains(number)) values.Insert(0, number); } return values; }
        private string CandidateRangeMessage() { return context.DisplayedTasks.Count == 0 ? "현재 선택할 수 있는 업무 목록이 없습니다. 먼저 업무 목록을 조회해 주세요." : "현재 선택 가능한 업무는 1번부터 " + context.DisplayedTasks.Count + "번까지입니다."; }
        private async Task<Guid?> ResolveContextTaskAsync(string input)
        {
            string normalizedInput = Normalize(input); if (Contains(normalizedInput, "방금 완료", "아까 완료", "최근 완료", "마지막 완료") && context.LastCompletedTaskId.HasValue) return context.LastCompletedTaskId; if (Contains(normalizedInput, "방금 수정", "아까 수정", "최근 수정", "마지막 수정", "방금 변경", "아까 변경") && context.LastModifiedTaskId.HasValue) return context.LastModifiedTaskId;
            if (IsPronounReference(input) || Contains(normalizedInput, "방금 업무", "방금 등록", "방금 만든", "아까 등록", "아까 만든", "마지막으로 등록", "그 업무", "그 작업")) { if (context.LastCreatedTaskId.HasValue && Contains(normalizedInput, "방금 등록", "방금 만든", "아까 등록", "아까 만든", "마지막으로 등록")) return context.LastCreatedTaskId; if (context.LastReferencedTaskId.HasValue) return context.LastReferencedTaskId; if (context.LastModifiedTaskId.HasValue) return context.LastModifiedTaskId; if (context.LastCreatedTaskId.HasValue) return context.LastCreatedTaskId; if (context.LastReadTaskIds.Count == 1) return context.LastReadTaskIds[0]; }
            string query = CleanTaskQuery(input); if (!string.IsNullOrWhiteSpace(query)) { IReadOnlyList<WorkTask> all = await tasks.GetAllAsync(); string[] tokens = Tokens(query); List<WorkTask> matches = all.Where(x => tokens.Length > 0 && tokens.All(t => Normalize(x.Title).Contains(t))).OrderByDescending(x => x.UpdatedAt).ToList(); if (matches.Count == 1) return matches[0].Id; }
            return null;
        }
        private async Task<AgentResponse> AskForTargetAsync() { IReadOnlyList<WorkTask> all = await tasks.GetAllAsync(); List<WorkTask> values = all.OrderByDescending(x => x.UpdatedAt).Take(5).ToList(); context.RecordRead(values.Select(x => x.Id)); context.SetDisplayedTasks(values, clock.Now); return Response(false, FormatCandidates("어떤 업무를 말씀하시는 건가요?", values), null); }
        private void LogDecision(string input, AgentDecision decision, bool fallbackUsed) { bool locked = IsStatusWriteRequest(input, "start_task") || IsStatusWriteRequest(input, "complete_task") || IsStatusWriteRequest(input, "block_task"); string finalIntent = locked ? "UPDATE_TASK" : decision == null ? "null" : decision.Type.ToString(); List<int> indexes = ExtractCandidateIndexes(input); string matches = string.Join(",", Regex.Matches(input ?? "", "\\d+\\s*번").Cast<Match>().Select(x => x.Value)); logger.Info("Agent Decision", "type=" + finalIntent + ",tools=" + (decision == null ? "" : string.Join(",", decision.Calls.Select(x => x.Tool))) + ",fallback=" + fallbackUsed + ",inputLength=" + (input ?? "").Length); logger.Info("Candidate Parser", "matches=" + matches + ",indexes=" + string.Join(",", indexes) + ",contextCount=" + context.DisplayedTasks.Count + ",resolution=" + (indexes.Any(x => x < 1 || x > context.DisplayedTasks.Count) ? "OutOfRange" : "Success")); logger.Info("Parser Resolution", "referencePhrase=" + ExtractReferencePhrase(input) + ",remainingAction=" + RemainingActionText(input) + ",explicitAction=" + DetectActionVerb(input) + ",normalizedStatus=" + (NormalizeStatus(input) ?? "none") + ",finalIntent=" + finalIntent + ",finalIntentLocked=" + locked + ",reason=" + (locked ? "explicit update action priority" : "NLP or read/status rule")); }

        private async Task<string> FormatBriefingAsync(AgentToolResult today, AgentToolResult history) { IList<WorkTask> values = today == null ? new List<WorkTask>() : today.Tasks; int todo = values.Count(x => x.Status == WorkTaskStatus.Todo), progress = values.Count(x => x.Status == WorkTaskStatus.InProgress), blocked = values.Count(x => x.Status == WorkTaskStatus.Blocked), done = values.Count(x => x.Status == WorkTaskStatus.Done && x.CompletedAt.HasValue && x.CompletedAt.Value.Date == clock.Now.Date); int syncErrors = values.Count(x => x.GitHubSyncStatus == GitHubSyncStatus.Pending || x.GitHubProjectSyncStatus == GitHubSyncStatus.Pending); context.RecordTaskSummary(todo); StringBuilder text = new StringBuilder("오늘 업무 현황입니다.\n\nTodo " + todo + "건\nIn Progress " + progress + "건\nBlocked " + blocked + "건\nDone " + done + "건"); foreach (WorkTask task in values.Where(x => x.Status == WorkTaskStatus.InProgress)) text.Append("\n- 진행 중: ").Append(task.Title); if (history != null) foreach (TaskHistory memo in history.History.Where(x => x.ActionType == TaskHistoryAction.MemoAdded && x.CreatedAt.Date == clock.Now.Date).Take(3)) { WorkTask task = await tasks.GetByIdAsync(memo.TaskId); text.Append("\n- 최근 메모: ").Append(task == null ? "업무" : task.Title).Append(" · ").Append(memo.Memo); } text.Append(syncErrors == 0 ? "\n\nGitHub Pending 동기화는 없습니다. 실제 Issue/Project 데이터 일치 여부는 별도 조회가 필요합니다." : "\n\nGitHub 동기화 대기 업무가 " + syncErrors + "건 있습니다."); return text.ToString(); }
        private async Task<string> FormatHistoryAsync(IList<TaskHistory> history) { List<TaskHistory> values = history.Where(x => x.CreatedAt.Date == clock.Now.Date || x.CreatedAt.Date == clock.Now.Date.AddDays(-1)).Take(15).ToList(); if (values.Count == 0) return "해당 기간에 기록된 업무 활동이 없습니다."; StringBuilder text = new StringBuilder("최근 업무 활동입니다."); foreach (TaskHistory item in values) { WorkTask task = await tasks.GetByIdAsync(item.TaskId); text.Append("\n- ").Append(task == null ? "삭제된 업무" : task.Title).Append(" · ").Append(item.ActionType); if (item.ActionType == TaskHistoryAction.MemoAdded) text.Append(" · ").Append(item.Memo); } return text.ToString(); }
        private static string FormatToday(IList<WorkTask> tasks) { return FormatStatusSummary("오늘 업무 현황",tasks); }
        private static string FormatRecent(IList<WorkTask> tasks, bool includeDescription = false) { WorkTask task = tasks.FirstOrDefault(); return task == null ? "최근 등록한 업무가 없습니다." : "방금 등록한 업무는 '" + task.Title + "'입니다." + (includeDescription ? "\n내용: " + (string.IsNullOrWhiteSpace(task.Description) ? "등록된 내용이 없습니다." : task.Description) : "") + (string.IsNullOrWhiteSpace(task.ExternalId) ? "" : " GitHub Issue #" + task.ExternalId + "에 연결되어 있습니다."); }
        private static string FormatTasks(IList<WorkTask> tasks, bool includeCreatedAt = false, bool includeDescription = false, string label = null) { string prefix = string.IsNullOrWhiteSpace(label) ? "" : label + " "; return tasks.Count == 0 ? (string.IsNullOrWhiteSpace(label) ? "조건에 맞는 업무가 없습니다." : label + (label.EndsWith("할 일") ? "이" : "가") + " 없습니다.") : prefix + tasks.Count + "건입니다.\n" + string.Join("\n", tasks.Select((x, i) => (i + 1) + ". " + x.Title + " - " + x.Status + (x.DueDate.HasValue ? " - " + DueDisplay(x.DueDate.Value) : "") + (includeCreatedAt ? "\n   등록: " + x.CreatedAt.ToString("yyyy-MM-dd HH:mm") : "") + (includeDescription ? "\n   내용: " + (string.IsNullOrWhiteSpace(x.Description) ? "등록된 내용이 없습니다." : x.Description) : ""))); }
        private static string FormatStatusSummary(string label,IList<WorkTask> tasks){StringBuilder text=new StringBuilder(label+" "+tasks.Count+"건입니다.");WorkTaskStatus[] statuses={WorkTaskStatus.Todo,WorkTaskStatus.InProgress,WorkTaskStatus.Blocked,WorkTaskStatus.Done};string[] names={"할 일","진행 중","보류","완료"};int number=1;for(int i=0;i<statuses.Length;i++){List<WorkTask> group=tasks.Where(x=>x.Status==statuses[i]).ToList();text.Append("\n\n").Append(names[i]).Append(" ").Append(group.Count).Append("건");foreach(WorkTask task in group)text.Append("\n").Append(number++).Append(". ").Append(task.Title);}return text.ToString();}
        private static string FormatAllSummary(IList<WorkTask> tasks){return FormatStatusSummary("현재 Workspace 전체 업무 현황",tasks);}
        private static string DueDisplay(DateTimeOffset value) { return value.Date == DateTime.Today ? "오늘" : value.Date == DateTime.Today.AddDays(1) ? "내일" : value.ToString("MM/dd"); }
        private static string FormatGitHubRefresh(IList<GitHubIssueInfo> issues) { GitHubIssueInfo issue = issues.OrderByDescending(x => x.CreatedAt).FirstOrDefault(); return issue == null ? "Repository에 Issue가 없습니다." : "최근 GitHub Issue는 #" + issue.Number + " " + issue.Title + "입니다." + (issue.IsTracked ? " SlaveSplit 업무에 연결되어 있습니다." : " 현재 SlaveSplit Local Task에는 연결되어 있지 않습니다."); }
        private static string FormatCandidates(string title, IList<WorkTask> tasks) { StringBuilder text = new StringBuilder(title); for (int i = 0; i < tasks.Count; i++) text.Append("\n").Append(i + 1).Append(". ").Append(tasks[i].Title); return text.ToString(); }
        private static string BuildDeletePreview(IList<WorkTask> tasks) { int todo = tasks.Count(x => x.Status == WorkTaskStatus.Todo), progress = tasks.Count(x => x.Status == WorkTaskStatus.InProgress), done = tasks.Count(x => x.Status == WorkTaskStatus.Done); StringBuilder text = new StringBuilder("삭제 후보 " + tasks.Count + "건을 찾았습니다.\nTodo " + todo + " · In Progress " + progress + " · Done " + done); for (int i = 0; i < tasks.Count; i++) text.Append("\n").Append(i + 1).Append(". ").Append(tasks[i].Title); text.Append("\n\n삭제하면 Local 업무가 제거됩니다. 연결된 GitHub Issue는 Close하고 Project는 Done으로 정리합니다. 이 업무들을 삭제할까요?"); return text.ToString(); }

        private static AgentDecision ParseDecision(string json)
        {
            try { JObject root = JObject.Parse(json); string type = ((string)root["type"] ?? "").ToLowerInvariant(); if (type == "message") return Message((string)root["content"]); if (type == "clarification") return Clarify((string)root["content"]); if (type == "tool_call") return DecisionFor(ParseCall(root), (bool?)root["write"] == true); if (type == "multi_tool") { JArray calls = root["calls"] as JArray; AgentDecision decision = new AgentDecision { Type = AgentDecisionType.MultiTool }; if (calls != null) foreach (JObject item in calls.OfType<JObject>()) decision.Calls.Add(ParseCall(item)); return decision.Calls.Count == 0 ? null : decision; } return null; } catch { return null; }
        }
        private static AgentToolCall ParseCall(JObject root) { AgentToolCall call = Call((string)root["tool"]); JObject args = root["arguments"] as JObject; if (args != null) foreach (var property in args.Properties()) call.Arguments[property.Name] = property.Value.Type == JTokenType.Null ? null : property.Value.ToString(); return call; }
        private static AgentDecision DecisionFor(AgentToolCall call, bool write) { AgentDecision value = new AgentDecision { Type = write ? AgentDecisionType.Write : AgentDecisionType.Read }; if (call != null) value.Calls.Add(call); return value; }
        private static AgentDecision Message(string value) { return new AgentDecision { Type = AgentDecisionType.Message, Content = value }; }
        private static AgentDecision Clarify(string value) { return new AgentDecision { Type = AgentDecisionType.Clarification, Content = value }; }
        private static AgentDecision Read(AgentToolCall call) { return DecisionFor(call, false); }
        private static AgentDecision Write(AgentToolCall call) { return DecisionFor(call, true); }
        private static AgentDecision WriteOrRead(AgentToolCall call, bool write) { return DecisionFor(call, write); }
        private static AgentDecision Multi(params AgentToolCall[] calls) { AgentDecision value = new AgentDecision { Type = AgentDecisionType.MultiTool }; foreach (AgentToolCall call in calls) value.Calls.Add(call); return value; }
        private static AgentToolCall Call(string tool) { return new AgentToolCall { Tool = tool }; }
        private static AgentToolCall Call(string tool, string key, string value) { AgentToolCall call = Call(tool); call.Arguments[key] = value; return call; }
        private static string Value(AgentToolCall call, string key) { string value; return call.Arguments.TryGetValue(key, out value) ? value : null; }
        private static AgentResponse Response(bool success, string message, Guid? taskId) { return new AgentResponse { Success = success, Message = message, RelatedTaskId = taskId, Intent = AgentIntent.Unknown }; }
        private static bool Contains(string value, params string[] candidates) { return candidates.Any(value.Contains); }
        private static string SafeLog(string value) { if (string.IsNullOrWhiteSpace(value)) return "none"; string text = value.Replace("\r", " ").Replace("\n", " "); return text.Length > 120 ? text.Substring(0, 120) : text; }
        private static string Normalize(string value) { return Regex.Replace((value ?? "").ToLowerInvariant(), "[^0-9a-z가-힣]+", " ").Trim(); }
        private static string[] Tokens(string value) { return Normalize(value).Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries).Where(x => x.Length > 1 && !new[] { "업무", "이슈", "그거", "그건", "메모", "상태" }.Contains(x)).ToArray(); }
        private static bool IsPronounReference(string value) { return Regex.IsMatch(value ?? "", "(그거|그 업무|그 작업|아까 그|아까 만든|방금 업무|방금 그 업무|아까 그 업무|방금 거|방금 만든|방금 등록한|마지막으로 등록한|방금 완료한|아까 완료한|최근 완료한|마지막 완료한|방금 수정한|아까 수정한|저거|그놈|그 건|그건|이거)"); }
        private static bool IsBriefing(string value) { return value.Contains("브리핑") || Contains(value, "오늘 업무 정리", "오늘 상황 알려"); }
        private static bool IsTodayQuestion(string value) { return value.Contains("오늘") && Contains(value, "뭐", "보여", "남았", "많아", "몇 개", "할거", "할 일", "이슈", "업무"); }
        private static bool IsSimpleDateReadQuery(string value) { string text = Normalize(value); bool date = Regex.IsMatch(text, "^(오늘|내일|어제|이번 ?주)(?:\\s|$)"); bool entity = Regex.IsMatch(text, "(업무|할 ?일|할일|뭐 해야)"); bool write = Regex.IsMatch(text, "(등록해|추가해|생성해|만들어|완료해|끝내|바꿔|변경해|삭제해|지워)"); return date && entity && !write; }
        private static bool IsGitHubRefresh(string value) { return (value.Contains("git") || value.Contains("github")) && Contains(value, "새로", "방금", "확인", "새 이슈"); }
        private static bool IsGitHubStatusQuestion(string value) { return (value.Contains("git") || value.Contains("github")) && Contains(value, "상태", "올라", "등록", "있어", "됐"); }
        private static bool IsDeleteRequest(string value) { return Contains(value, "삭제", "지워", "싹 정리", "다 지우", "정리해"); }
        private static bool IsMemoRequest(string value) { if (IsCreateRequest(value)) return false; return Regex.IsMatch(value ?? "", "(?:^|\\s)메모(?:\\s|$)") || Contains(value, "진행사항", "기록 남", "코멘트", "댓글", "요청했", "확인 중", "기다리는 중"); }
        private static bool IsDescriptionRequest(string value) { if (Regex.IsMatch(value ?? "", "제목(?:은|으로|:)")) return false; return Regex.IsMatch(value ?? "", "(?:업무\\s*)?(?:내용|설명|description|본문)(?:에|을|은|:)", RegexOptions.IgnoreCase); }
        private static bool IsDescriptionWriteRequest(string value) { return IsDescriptionRequest(value) && Regex.IsMatch(value ?? "", "(적어|써|작성|바꿔|수정|추가|넣어)", RegexOptions.IgnoreCase); }
        private static bool IsClearConversationRequest(string value) { string text = Normalize(value); return Contains(text, "대화", "대화창", "채팅", "채팅 기록", "새 대화") && Contains(text, "지워", "삭제", "초기화", "비워", "없애", "새로 시작", "새 대화 시작"); }
        private static bool IsCreateRequest(string value) { bool action = Contains(value, "등록", "추가", "생성", "만들", "할 일에 넣"); bool entity = Contains(value, "업무", "할 일", "작업", "제목은", "제목으로"); return action && entity; }
        private static bool HasAmbiguousTime(string value){string text=value??"";return Regex.IsMatch(text,"(?<!오전\\s)(?<!오후\\s)(?<!\\d)(?:[1-9]|1[0-2])\\s*시(?:까지|에|로|\\s)")&&!Regex.IsMatch(text,"(?:오전|오후)\\s*(?:[1-9]|1[0-2])\\s*시");}
        private static bool IsRecentReferenceAction(string value) { string text = Normalize(value); return Regex.IsMatch(text, "(방금|아까|마지막으로)\\s*(등록한|만든)\\s*(업무|작업|이슈)") && Regex.IsMatch(text, "(바꿔|바꾸|변경|수정|완료|삭제|지워|메모|진행중으로|진행 중으로|시작)"); }
        private static bool IsConfirm(string value) { return Regex.IsMatch((value ?? "").Trim(), "^(확인|진행|진행해|해|응|ㅇㅇ|그래|맞아|삭제해|완료해|지워|ok|오케이)[.! ]*$", RegexOptions.IgnoreCase); }
        private static bool IsCancel(string value) { string text = (value ?? "").Trim(); return Regex.IsMatch(text, "^(아니|ㄴㄴ|취소|취소해|하지마|안해|됐어)[.! ]*$", RegexOptions.IgnoreCase) || text.Contains("취소") || text.Contains("하지마"); }
        private static string CleanCreateTitle(string value) { string text = Regex.Replace(value ?? "", "^(오늘|내일|어제|\\d{1,2}\\s*월\\s*\\d{1,2}\\s*일)\\s*", ""); text = Regex.Replace(text, "\\s*업무(로)?\\s*(등록|추가).*$", "", RegexOptions.IgnoreCase); text = Regex.Replace(text, "(등록|추가)해\\s*줘.*$", "", RegexOptions.IgnoreCase); return text.Trim(' ', '.', '!', '?'); }
        private static string CleanTaskQuery(string value) { string text = Regex.Replace(value ?? "", "(그거|그 업무|아까 그거|아까 그 이슈|방금 거|저거|그놈|그 건|그건|이거)", " "); text = Regex.Replace(text, "(시작했어?|시작할게|완료|끝났어?|끝냈어?|다 했어?|다시 열어?|막혔어?|github.*|git.*|메모.*|내용.*)", " ", RegexOptions.IgnoreCase); return Regex.Replace(text, "\\s+", " ").Trim(' ', '.', '!', '?'); }
        private static string ExtractMemo(string value) { Match match = Regex.Match(value ?? "", "(?:그거|그 업무|그 작업|그 건|그건|아까 만든 (?:업무|이슈)|방금 업무|방금 만든 (?:업무|거))?(?:에|의)?\\s*(.+?)(?:라고)?\\s*(?:메모(?:를|로|에)?\\s*)?(?:적어줘|써줘|써놔|기록해|남겨)(?:줘)?[.!? ]*$"); string memo = match.Success ? match.Groups[1].Value.Trim() : (Contains(Normalize(value), "요청했", "확인 중", "기다리는 중") ? (value ?? "").Trim(' ', '.', '!', '?') : null); return !string.IsNullOrWhiteSpace(memo) && !(IsPronounReference(memo) && memo.Length < 15) ? memo : null; }
        private static string ExtractReadKeyword(string value) { string text = Normalize(value); text = Regex.Replace(text, "\\d+\\s*(개|건)?", " "); text = Regex.Replace(text, "(지금|현재|오늘|내일|어제|이번 ?주|today|내가|나의|할일|할 ?일|진행 ?중인?|진행|작업 ?중|하고 있는|해야|할 ?거|예정된?|todo|done|완료된|완료한?|끝난|것|업무|작업|이슈|내용|설명|본문|제목하고|제목|등록 ?시간|생성 ?시간|몇 ?개야|몇개야|뭐 ?있어|뭐있어|뭐야|뭐|있는데|있어|보여 ?줘|보여줘|보여|확인해 ?봐|확인해봐|확인해|확인|마지막으로|등록한|관련|관한|대해서|찾아 ?줘|찾아봐|찾아|조회해|조회|알려 ?줘|알려줘)", " ", RegexOptions.IgnoreCase); text = Regex.Replace(text, "(^|\\s)(은|는|이|가|에|만|일)(?=\\s|$)", " "); return Regex.Replace(text, "\\s+", " ").Trim(); }
        private static bool IsLikelyTaskRead(string value) { string text = Normalize(value); if (Contains(text, "삭제", "지워", "완료로", "완료해", "등록해", "추가해", "메모", "시작해", "바꾸")) return false; return Contains(text, "업무", "이슈", "task") && Contains(text, "있어", "뭐", "보여", "확인", "찾아", "알려"); }
        private static bool IsStatusQuestion(string value) { bool status = NormalizeStatus(value) != null; bool explicitWrite = IsStatusWriteRequest(value, "start_task") || IsStatusWriteRequest(value, "complete_task") || IsStatusWriteRequest(value, "block_task") || Regex.IsMatch(Normalize(value), "(수정해|삭제해|지워)"); return status && !explicitWrite; }
        private static string NormalizeStatus(string value) { string text = Normalize(value); if (Regex.IsMatch(text, "(in ?progress|진행 ?중|진행 업무|작업 ?중|처리 ?중|하고 있는|현재 하는)")) return "InProgress"; if (Regex.IsMatch(text, "(done|완료|끝난|끝낸|처리 ?완료)")) return "Done"; if (Regex.IsMatch(text, "(todo|할 ?일|해야 ?할 ?일|대기|미진행)")) return "Todo"; return null; }
        private static string ExtractReferencePhrase(string value) { Match match = Regex.Match(value ?? "", "((?:방금|아까|마지막으로)\\s*(?:등록한|만든|완료한|수정한|변경한)\\s*(?:업무|작업|이슈))"); return match.Success ? match.Groups[1].Value : "none"; }
        private static string RemainingActionText(string value) { string reference = ExtractReferencePhrase(value); return reference == "none" ? Normalize(value) : Normalize((value ?? "").Replace(reference, " ")); }
        private static bool IsStatusWriteRequest(string value, string tool) { string text = Normalize(value); if (tool == "complete_task") return Regex.IsMatch(text, "(완료\\s*로\\s*(변경|바꿔|바꾸|하자)|done\\s*으로\\s*(변경|바꿔|바꾸|하자)|완료\\s*(해|처리)|끝났|끝냈|다 했|(?:번|마지막거|마지막 것|전체 다|전부)\\s*완료)"); if (tool == "start_task") return Regex.IsMatch(text, "((진행|진행중|진행 중|inprogress|in progress)\\s*으로\\s*(변경|바꿔|바꾸)|시작\\s*(해|했|할게)|진행 시작)"); return Regex.IsMatch(text, "(대기 상태\\s*로\\s*(변경|바꿔)|막혔|blocked\\s*로\\s*(변경|바꿔))"); }
        private static string DetectActionVerb(string value) { Match match = Regex.Match(Normalize(value), "(등록해|추가해|만들어|변경해|변경|바꿔|완료해|삭제해|지워|메모 남겨|수정해|시작해)"); return match.Success ? match.Value : "none"; }
        private static string DetectReadExpression(string value) { Match match = Regex.Match(Normalize(value), "(보여줘|보여|확인해봐|확인해|확인|찾아줘|찾아봐|조회해|알려줘|있어|몇 개야|몇개야|뭐야)"); return match.Success ? match.Value : "none"; }
        private string DescribeState() { PendingAgentAction pending = context.PendingAction; return "pending=" + (pending == null ? "none" : pending.ActionType + "/" + pending.Need) + ",candidates=" + context.DisplayedTasks.Count + ",lastReferenced=" + Id(context.LastReferencedTaskId) + ",lastModified=" + Id(context.LastModifiedTaskId) + ",lastCompleted=" + Id(context.LastCompletedTaskId) + ",lastDeleted=" + Id(context.LastDeletedTaskId) + ",lastRead=" + context.LastReadTaskIds.Count; }
        private static string Id(Guid? value) { return value.HasValue ? value.ToString() : "none"; }
        private static bool IsTargetWrite(string tool) { return tool == "start_task" || tool == "complete_task" || tool == "reopen_task" || tool == "block_task" || tool == "add_task_memo" || tool == "update_task_description" || tool == "update_task_due_date" || tool=="update_task_priority" || tool=="update_task_time" || tool=="update_task_reminder" || tool == "create_github_issue" || tool == "retry_github_sync"; }
        private static bool RequiresTask(string tool) { return tool == "get_task" || tool == "start_task" || tool == "complete_task" || tool == "reopen_task" || tool == "block_task" || tool == "add_task_memo" || tool == "update_task_description" || tool == "update_task_due_date" || tool=="update_task_priority" || tool=="update_task_time" || tool=="update_task_reminder" || tool == "get_task_github_status" || tool == "create_github_issue" || tool == "retry_github_sync"; }
    }
}
